INSERT INTO `blogs` (`id`, `category_id`, `title`, `details`, `photo`, `source`, `views`, `status`, `meta_tag`, `meta_description`, `tags`, `created_at`) VALUES
(48, 9, 'Urutonde Rw\'imbuga 6 zikora nka Youtube utaruzi ushobora kuba wakoreraho amafaranga.', '<p><span style=\"font-size:18.0pt\">Abantu benshi iyo ubabajije urubuga ushobora gukuraho amashusho,indirimbo,utuntu dusekeje&nbsp; byoroshye ndetse ukaba ushobora gukoreraho amafaranga, igisubizo bahita baguha ni Youtube, aho unasanga bumva ko ari yo yonyine ikora gutyo.</span></p>\r\n\r\n<p><span style=\"font-size:18.0pt\">Muhahe.com twagukoreye urutonde rw&rsquo;imbuga 6 zikora kimwe na Youtube ushobora kwifashisha ukaba wanakorera amafaranga bitewe nibisabwa bigenderwaho.</span></p>\r\n\r\n<p><span style=\"font-size:18.0pt\">1. </span><a href=\"http://www.jdoqocy.com/click-7251228-12984344/\" target=\"_blank\"><span style=\"font-size:18.0pt\">Vimeo</span></a></p>\r\n\r\n<p><span style=\"font-size:12.0pt\">&nbsp;</span><img src=\"https://i.imgur.com/lG8MVzl.png\" width=\"422\" /></p>\r\n\r\n<p><span style=\"font-size:12.0pt\">&nbsp;</span></p>\r\n\r\n<p><span style=\"font-size:14.0pt\">Niba usanzwe ukoresha cyangwa wifashisha YouTube kenshi urebaho indirimbo hamwe n&rsquo;ibindi biganiro bitandukanye menyako Vimeo nayo ikora neza nka YouTube.</span></p>\r\n\r\n<p><span style=\"font-size:14.0pt\">Vimeo kandi ushobora gukurikiranaho film z&rsquo;uruhererekane zitandukanye muburyo bworoshye.</span></p>\r\n\r\n<p><span style=\"font-size:12.0pt\">&nbsp;</span>2. <a href=\"http://www.metacafe.com/\" target=\"_blank\">Metacafe</a></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"font-size:12.0pt\">&nbsp;</span><img src=\"https://i.imgur.com/LjMnkkI.jpg\" width=\"309\" /></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"font-size:14.0pt\">Ushaka gukurikirana inkuru zigezweho zavuzweho cyane burimunsi muburyo bw&rsquo;amashusho, kumenya birambuye kubyagiye bivugwa kub&rsquo;icuruzwa bitandukanye ndetse nuko ushobora kubigenza ngo urenge ibice (difficult level) bikomeye igihe ukina imikino ya mudasobwa cyangwa iya telephone (video game) wagana uru rubuga rwa Metacafe, ikindi nuko rukoresha amashusho magufi ugereranije nuko Youtube ikora, bityo bituma utarambirwa vuba kuko ubutumwa ukeneye kureba ububona bitagutwara umwanya munini. Ikindi nuko byorohera abashyira amashusho kuri uru rubuga kuba bashobora gukora amashusho menshi k&rsquo;umunsi kubera igihe gitoya baba bemerewe.&nbsp;&nbsp; </span></p>\r\n\r\n<p><span style=\"font-size:18.0pt\">3. </span><span style=\"font-size:18.0pt\"><a href=\"https://www.dailymotion.com/\" target=\"_blank\">Dailymotion</a></span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"font-size:12.0pt\">&nbsp;</span><img src=\"https://i.imgur.com/5FwT0M1.jpg\" width=\"280\" /></p>\r\n\r\n<p><span style=\"font-size:14.0pt\">Dailymotion niyo iza kwisonga mu guhangana na YouTube kuko imaze igihe itangiye gukora aho yatangijwe mu mwaka wa 2005.kugeza ubu ikurikiranwa n&rsquo;abantu benshi kandi usanga imikorere yayo ntaho ijya gutandukanira n&rsquo;iya Youtube kuko benshi bakekako izi mbuga zombi ari iz&rsquo;umuntu umwe.</span></p>\r\n\r\n<p><span style=\"font-size:18.0pt\">4. </span><a href=\"http://www.crackle.com/\" target=\"_blank\"><span style=\"font-size:18.0pt\">Crackle</span></a></p>\r\n\r\n<p><span style=\"font-size:12.0pt\">&nbsp;</span><img src=\"https://i.imgur.com/5JRs7jF.jpg\" width=\"422\" /></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"font-size:14.0pt\">Crackle ni urubuga rwashinzwe na Sony Pictures Entertainment, rukaba ahanini runyuzaho amashusho urebera kuri murandasi by&rsquo;akokanya (online streaming). Wahasanga ibiganiro bitandukanye by&rsquo;ama television atandukanye ndetse n&rsquo;ama film yagacishisheho mu myaka yashize ikindi nuko amashusho yose yatunganijwe n&rsquo;uru ruganda rwa Sony Pictures Entertainment wayahasanga. </span></p>\r\n\r\n<p><span style=\"font-size:18.0pt\">5.</span>&nbsp;<span style=\"background-color:#ffffff; font-size:18pt\"><a href=\"https://www.ted.com/talks\" style=\"background-color: rgb(255, 255, 255);\" target=\"_blank\">TED Talks</a></span>&nbsp;<img src=\"https://i.imgur.com/6alctvC.jpg\" width=\"422\" /></p>\r\n\r\n<p><span style=\"font-size:14.0pt\">Niba wifuza kujya ukurikirana amashusho avuga kubijyanye n&rsquo;iterambere,ubukungu, inganda, ubukerarugendo, ubuvanganzo ndetse hamwe n&rsquo;ibindi bibazo birikuvugwaho cyane ku isi hose ntahandi wagana uretse kuri uru rubuga bita TED Talks,ibiganiro bicaho biba biri mubwoko butandukandukanye kuburyo byorohereza umuntu kuba yabona icyo ashaka byihuse, ndetse k&rsquo;ubantu bakunda kureba amashusho magufi hariho uburyo video itarengeje iminota 6 iba ifite akaziga gatukura hejuru.</span></p>\r\n\r\n<p><span style=\"font-size:18.0pt\">6. TikTok</span></p>\r\n\r\n<p><span style=\"font-size:12.0pt\">&nbsp;</span><img src=\"https://i.imgur.com/uBqsuG9.jpg\" width=\"422\" /></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"font-size:14.0pt\">TikTok ni urubuga rukorera mugihugu cy&rsquo;ubushinwa ruhanganye cyane na Youtube muri uyumwaka wa 2020, umwahariko wayo ni uburyo rukozwemo bubereye ijisho ikindi ni ukuntu rworohereza abarukoresha kuba bashyiraho ibihangano cyangwa amashusho bifuza yose bijya gutandukanaho gato n&rsquo;uburyo Youtube ishyiraho amabwiriza akakaye .</span></p>\r\n\r\n<p><span style=\"font-size:14.0pt\">Ikindi n&rsquo;uko umuntu ukoresha application ya TikTok muri telephone ye aba afite uburyo bwo kunoza amashusho mbere yuko ayashyira kuri murandasi&nbsp; bukoranye n&rsquo;iriya application (built-in video editors)&nbsp; bidasabye kubushaka iruhande. Ikaba kandi ikorana na Adobe Premiere Rush, PicsArt, and Fuse byoroshye kuburyo amashusho uri gutunganyiriza muri&nbsp; imwe muri ziriya program ziba zifite uburyo ushobora guhita ushyira ayo mashusho kurubuga rwa TikTok bitakugoye.</span></p>\r\n\r\n<h1>&nbsp;</h1>', '159280990814337203_f1024.jpg', 'muhahe.com', 1329, 1, 'Muhahe Ltd,urutonde,imbugankoranyambaga', '<p>Urutonde Rw&#39;imbuga 6 zikora nka Youtube utaruzi ushobora kuba wakoreraho amafaranga.</p>', 'muhahe.com', '2020-05-25 19:09:06'),
(49, 8, 'Menya ibintu 5 by\'ingenzi ugomba kwirinda gukora kugira battery ya telephone yawe irambe.', '<p class=\"MsoNormal\" style=\"margin-bottom:0cm;margin-bottom:.0001pt;line-height:\r\nnormal\"><b><span style=\"font-size:16.0pt;font-family:\" times=\"\" new=\"\" roman\",\"serif\";=\"\" mso-fareast-font-family:\"times=\"\" roman\"\"=\"\">Uko telefone yawe yaba imarana igihe\r\nkirekire umuriro, nta telefone idashiramo umuriro. Kandi uko batiri yaba\r\nikomeye kose, nta yidasaza nyuma y’igihe runaka. Itandukaniro rishobora\r\nkugaragara ku ma telephone ni iry’igihe ishobora kuramba n’igihe ishobora\r\nkwangirika.</span></b><span style=\"font-size:16.0pt;font-family:\" times=\"\" new=\"\" roman\",\"serif\";=\"\" mso-fareast-font-family:\"times=\"\" roman\"\"=\"\"><o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\" style=\"mso-margin-top-alt:auto;mso-margin-bottom-alt:auto;\r\nline-height:normal\"><b><span style=\"font-size:16.0pt;font-family:\" times=\"\" new=\"\" roman\",\"serif\";=\"\" mso-fareast-font-family:\"times=\"\" roman\"\"=\"\">Akenshi usanga ibyo dutunze muri\r\ntelephone zacu, ubwoko cyangwa umubare wa Application zirimo ndetse n’uburyo\r\ntuzishyira ku muriro ari byo byangiza telefone zacu. twifashishije urubuga rwa\r\nPower Technology twabateguriye ibintu ukwiriye kwirinda gukorera telefone yawe kuko\r\nibyo bintu biteza ingaruka mbi ku burambe bwa batiri yayo.</span></b><span style=\"font-size:16.0pt;font-family:\" times=\"\" new=\"\" roman\",\"serif\";mso-fareast-font-family:=\"\" \"times=\"\" roman\"\"=\"\"> <o:p></o:p></span></p><p class=\"MsoNormal\" style=\"mso-margin-top-alt:auto;mso-margin-bottom-alt:auto;\r\nline-height:normal\"><b><span style=\"font-size:16.0pt;font-family:\" times=\"\" new=\"\" roman\",\"serif\";=\"\" mso-fareast-font-family:\"times=\"\" roman\"\"=\"\"><br></span></b></p>\r\n\r\n<p class=\"MsoNormal\" style=\"mso-margin-top-alt:auto;mso-margin-bottom-alt:auto;\r\nline-height:normal\"><b><span style=\"font-size:20.0pt;font-family:\" times=\"\" new=\"\" roman\",\"serif\";=\"\" mso-fareast-font-family:\"times=\"\" roman\"\"=\"\">1. Irinde Guhoza telefone yawe ku\r\nmuriro cyangwa kuyiraza icometse k’umuriro</span></b><span style=\"font-size:\r\n20.0pt;font-family:\" times=\"\" new=\"\" roman\",\"serif\";mso-fareast-font-family:\"times=\"\" roman\"\"=\"\"><o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\" style=\"mso-margin-top-alt:auto;mso-margin-bottom-alt:auto;\r\nline-height:normal\"><span style=\"font-size:16.0pt;font-family:\" times=\"\" new=\"\" roman\",\"serif\";=\"\" mso-fareast-font-family:\"times=\"\" roman\"\"=\"\">Ubundi buri telefone igira urwego\r\nntarengwa rw’umuriro, kumva ushaka kurenza urwo rwego bizangiza telefone yawe.\r\nAbenshi baraza telefone zabo ku muriro kugira ngo babyuke zuzuye bakore gahunda\r\nzabo nta kibazo cy’umuriro bafite muri uwo munsi, ibintu byangiza cyane\r\nubudahangarwa bwa batiri ya telefone ariko abenshi tukaba batabizi.<o:p></o:p></span></p><p class=\"MsoNormal\" style=\"mso-margin-top-alt:auto;mso-margin-bottom-alt:auto;\r\nline-height:normal\"><img src=\"https://i.imgur.com/9Ty8SNj.jpg\" width=\"422\"><span style=\"font-size:16.0pt;font-family:\" times=\"\" new=\"\" roman\",\"serif\";=\"\" mso-fareast-font-family:\"times=\"\" roman\"\"=\"\"><br></span></p><p class=\"MsoNormal\" style=\"mso-margin-top-alt:auto;mso-margin-bottom-alt:auto;\r\nline-height:normal\"><b><i><span style=\"font-size:16.0pt;font-family:\" times=\"\" new=\"\" roman\",\"serif\";=\"\" mso-fareast-font-family:\"times=\"\" roman\"\"=\"\">Gushyira telefone ku muriro ikuzura\r\nikarenza urugero si byiza</span></i></b><br></p>\r\n\r\n<p class=\"MsoNormal\" style=\"mso-margin-top-alt:auto;mso-margin-bottom-alt:auto;\r\nline-height:normal\"><span style=\"font-size:16.0pt;font-family:\" times=\"\" new=\"\" roman\",\"serif\";=\"\" mso-fareast-font-family:\"times=\"\" roman\"\"=\"\">Aha umuntu ashobora kwibaza ibibi\r\nbyabyo kandi bituma nyiri terefone abyuka yuzuye, gusa urugero twakwifashisha\r\nhano; uri gushyira amabuye mu mufuka ukuzura, ugakomeza gushyiramo ayandi\r\nbyagenda gute? Na telefone ni telefone rero mu gihe uryamye wasinziriye,\r\niruzura ikarenza kuzura. Aho byaba byiza byibuze mu gihe yuzuye ugiye uhita\r\nuyikuraho ako kanya bikayirinda kwangirika.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\" style=\"mso-margin-top-alt:auto;mso-margin-bottom-alt:auto;\r\nline-height:normal\"><b><span style=\"font-size:20.0pt;font-family:\" times=\"\" new=\"\" roman\",\"serif\";=\"\" mso-fareast-font-family:\"times=\"\" roman\"\"=\"\">2.</span></b><span style=\"font-size: 20pt; font-weight: bolder;\">&nbsp;</span><span style=\"font-size: 20pt; font-weight: bolder;\">Irinde</span><span style=\"font-size: 20pt; font-weight: bolder;\">&nbsp;</span><b><span style=\"font-size:20.0pt;font-family:\" times=\"\" new=\"\" roman\",\"serif\";=\"\" mso-fareast-font-family:\"times=\"\" roman\"\"=\"\">Gukoresha Sharijeri zitujuje\r\nubuziranenge.</span></b></p>\r\n\r\n<p class=\"MsoNormal\" style=\"mso-margin-top-alt:auto;mso-margin-bottom-alt:auto;\r\nline-height:normal\"><span style=\"font-size:16.0pt;font-family:\" times=\"\" new=\"\" roman\",\"serif\";=\"\" mso-fareast-font-family:\"times=\"\" roman\"\"=\"\">Mu buzima bwose nta wanga\r\nicyoroshye, kandi abantu benshi usanga dukunda ibihendutse cyane, nyamara\r\nakenshi ugasanga bitanaramba. Nka sharijeri za telefone, hari uwihutira\r\nkuyigura kuko ihendutse ariko ugasanga ubuziranenge bwayo burakemangwa ndetse\r\nbukaba bwanakwangiriza telefone yawe na batiri yayo.<o:p></o:p></span></p><p class=\"MsoNormal\" style=\"mso-margin-top-alt:auto;mso-margin-bottom-alt:auto;\r\nline-height:normal\"><img src=\"https://i.imgur.com/R5D9Q8j.jpg\" width=\"422\"><span style=\"font-size:16.0pt;font-family:\" times=\"\" new=\"\" roman\",\"serif\";=\"\" mso-fareast-font-family:\"times=\"\" roman\"\"=\"\"><br></span></p>\r\n\r\n<p class=\"MsoNormal\" style=\"mso-margin-top-alt:auto;mso-margin-bottom-alt:auto;\r\nline-height:normal\"><b><i><span style=\"font-size:16.0pt;font-family:\" times=\"\" new=\"\" roman\",\"serif\";=\"\" mso-fareast-font-family:\"times=\"\" roman\"\"=\"\">Gukoresha sharijeri zitujuje\r\nubuziranenge</span></i></b><span style=\"font-size:16.0pt;font-family:\" times=\"\" new=\"\" roman\",\"serif\";=\"\" mso-fareast-font-family:\"times=\"\" roman\"\"=\"\"><o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\" style=\"mso-margin-top-alt:auto;mso-margin-bottom-alt:auto;\r\nline-height:normal\"><span style=\"font-size:16.0pt;font-family:\" times=\"\" new=\"\" roman\",\"serif\";=\"\" mso-fareast-font-family:\"times=\"\" roman\"\"=\"\">Ubundi buri telefone izana na\r\nsharijeri yayo, jya uba ariyo ukoresha ushyiramo umuriro, niba utanayifite\r\nbitewe n’impamvu, gerageza gushaka iyo bijyanye abazicuruza bagufasha kumenya\r\niy’ukuri kuko usanga ingano y’umuriro zinjiza iba itangana bityo rero iyo wowe\r\nwihutiye kugura iya make utitaye ku ijyanye na telefone ufite usanga ingaruka\r\nzigaruka kuri bateri yawe.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\" style=\"mso-margin-top-alt:auto;mso-margin-bottom-alt:auto;\r\nline-height:normal\"><b><span style=\"font-size:20.0pt;font-family:\" times=\"\" new=\"\" roman\",\"serif\";=\"\" mso-fareast-font-family:\"times=\"\" roman\"\"=\"\">3.</span></b><span style=\"font-size: 20pt; font-weight: bolder;\">&nbsp;</span><span style=\"font-size: 20pt; font-weight: bolder;\">Irinde</span><span style=\"font-size: 20pt; font-weight: bolder;\">&nbsp;</span><b><span style=\"font-size:20.0pt;font-family:\" times=\"\" new=\"\" roman\",\"serif\";=\"\" mso-fareast-font-family:\"times=\"\" roman\"\"=\"\">Gukoresha telefone yawe iri ku\r\nmuriro.</span></b></p><p class=\"MsoNormal\" style=\"mso-margin-top-alt:auto;mso-margin-bottom-alt:auto;\r\nline-height:normal\"><img src=\"https://i.imgur.com/nNR6L8P.jpg\" width=\"422\"><b><span style=\"font-size:20.0pt;font-family:\" times=\"\" new=\"\" roman\",\"serif\";=\"\" mso-fareast-font-family:\"times=\"\" roman\"\"=\"\"><br></span></b></p>\r\n\r\n<p class=\"MsoNormal\" style=\"mso-margin-top-alt:auto;mso-margin-bottom-alt:auto;\r\nline-height:normal\"><span style=\"font-size:16.0pt;font-family:\" times=\"\" new=\"\" roman\",\"serif\";=\"\" mso-fareast-font-family:\"times=\"\" roman\"\"=\"\">Iyo telefone iri ku muriro, uri no\r\ngukina imikino, kuganira n’abantu ku mbuga nkoranyambaga, kuvugana n’abantu\r\nwitaba cyangwa uhamagara n’ibindi, binaniza cyane batiri ya telefone yawe,\r\nugasanga no kwinjiza umuriro ni ikibazzo gikomeye, bityo ikamara umwanya munini\r\nku muriro ugereranije n’uwo isanzwe imaraho kandi bikanayigabanyiriza\r\nubudahangarwa busanzwe ikajya imarana umuriro umwanya muto.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\" style=\"margin-bottom:0cm;margin-bottom:.0001pt;line-height:\r\nnormal\"><span style=\"font-size:16.0pt;font-family:\" times=\"\" new=\"\" roman\",\"serif\";=\"\" mso-fareast-font-family:\"times=\"\" roman\"\"=\"\"><o:p>&nbsp;</o:p></span></p>\r\n\r\n<p class=\"MsoNormal\" style=\"mso-margin-top-alt:auto;mso-margin-bottom-alt:auto;\r\nline-height:normal\"><b><span style=\"font-size:20.0pt;font-family:\" times=\"\" new=\"\" roman\",\"serif\";=\"\" mso-fareast-font-family:\"times=\"\" roman\"\"=\"\">4.</span></b><span style=\"font-size: 20pt; font-weight: bolder;\">&nbsp;</span><span style=\"font-size: 20pt; font-weight: bolder;\">Irinde</span><span style=\"font-size: 20pt; font-weight: bolder;\">&nbsp;</span><b><span style=\"font-size:20.0pt;font-family:\" times=\"\" new=\"\" roman\",\"serif\";=\"\" mso-fareast-font-family:\"times=\"\" roman\"\"=\"\">Gutereka telefone hasi iri ku\r\nmuriro.</span></b></p><p class=\"MsoNormal\" style=\"mso-margin-top-alt:auto;mso-margin-bottom-alt:auto;\r\nline-height:normal\"><img src=\"https://i.imgur.com/BYQUFFK.jpg\" width=\"422\"><b><span style=\"font-size:20.0pt;font-family:\" times=\"\" new=\"\" roman\",\"serif\";=\"\" mso-fareast-font-family:\"times=\"\" roman\"\"=\"\"><br></span></b></p>\r\n\r\n<p class=\"MsoNormal\" style=\"mso-margin-top-alt:auto;mso-margin-bottom-alt:auto;\r\nline-height:normal\"><span style=\"font-size:16.0pt;font-family:\" times=\"\" new=\"\" roman\",\"serif\";=\"\" mso-fareast-font-family:\"times=\"\" roman\"\"=\"\">Akenshi usanga bitewe n’aho dushyize\r\nku muriro haba hegereye hasi, telefone tugahita tuyishyira ku isima hasi\r\ncyangwa ku makaro ibintu byangiza cyane ubuzima bwa batiri za telefone zacu\r\nkuko imikoranire y’iyo sima cyangwa ayo makaro n’iyo batiri bidahura. Ibyiza ni\r\nuko washaka umwenda ukoze muri coton, atari niron cyangwa ugashaka ikintu cya\r\nkawuco cyangwa gikoze mu giti nk’intebe cyangwa ameza, ugaterekaho terefone\r\nyawe.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\" style=\"mso-margin-top-alt:auto;mso-margin-bottom-alt:auto;\r\nline-height:normal\"><b><span style=\"font-size:20.0pt;font-family:\" times=\"\" new=\"\" roman\",\"serif\";=\"\" mso-fareast-font-family:\"times=\"\" roman\"\"=\"\">5.</span></b><span style=\"font-size: 20pt; font-weight: bolder;\">&nbsp;</span><span style=\"font-size: 20pt; font-weight: bolder;\">Irinde</span><span style=\"font-size: 20pt; font-weight: bolder;\">&nbsp;</span><b><span style=\"font-size:20.0pt;font-family:\" times=\"\" new=\"\" roman\",\"serif\";=\"\" mso-fareast-font-family:\"times=\"\" roman\"\"=\"\">Kuvana telefone ku muriro ituzuye.</span></b></p><p class=\"MsoNormal\" style=\"mso-margin-top-alt:auto;mso-margin-bottom-alt:auto;\r\nline-height:normal\"><img src=\"https://i.imgur.com/11ixaf3.jpg\" width=\"444\"><b><span style=\"font-size:20.0pt;font-family:\" times=\"\" new=\"\" roman\",\"serif\";=\"\" mso-fareast-font-family:\"times=\"\" roman\"\"=\"\"><br></span></b></p>\r\n\r\n<p class=\"MsoNormal\" style=\"mso-margin-top-alt:auto;mso-margin-bottom-alt:auto;\r\nline-height:normal\"><span style=\"font-size:16.0pt;font-family:\" times=\"\" new=\"\" roman\",\"serif\";=\"\" mso-fareast-font-family:\"times=\"\" roman\"\"=\"\">Ubundi iyo telefoni iri ku muriro\r\nbirakwiye ko uyiha agahenge ikabanza ikagera kuri rwa rwego rwayo rwa nyuma.\r\nIyo uyivanyeho itaruzura, biyitera gusubira inyuma no gucika intege kwa batiri.\r\nIkindi ni ukuyishyira ku muriro hakirimo uwundi. Ugasanga iri kuri 56%\r\nukayishyira ku muriro, ibyiza ni uko wajya uyireka ukayishyira ku muriro\r\nitangiye kukwereka ko ifite imbaraga nke zo gukomeza gukora aha twavuga igihe\r\nnibura igeze kuri 20%, wanayishyira ku muriro ukayireka ikagera ku 100%\r\nukayikoresha nanone yageza cyagihe ikwereka ko umuriro ugiye gushiramo ukongera\r\nukayishyira ku muriro.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\"><span style=\"font-size:16.0pt;line-height:115%;font-family:\r\n\" times=\"\" new=\"\" roman\",\"serif\"\"=\"\">Nibyiza kubungabunga ubusugire bwa telefone yawe\r\nwita kuri batiri yayo kuko akenshi &nbsp;iyo\r\nigize ikibazo bikagusaba kugura indi bateri yo kuyisimbuza bigutwara amafaranga\r\nmenshi kandi iyo bashyiramo ugasanga&nbsp; iba\r\nitanakomeye nk’iyazanye na telefone.<o:p></o:p></span></p>', '1590498097log.JPG', 'muhahe.com', 1082, 1, 'Muhahe Ltd', 'Menya ibintu 5 by\'ingenzi ugomba kwirinda gukora kugira battery ya telephone yawe irambe.<br>', 'muhahe.com', '2020-05-26 11:01:37'),
(50, 8, 'Menya uko Uko aba Hackers bashobora kwinjira mu mabanga yawe nuko wabirinda.', '<p style=\"margin-right: 0px; margin-bottom: 14px; margin-left: 0px; padding: 0px; color: rgb(102, 102, 102); font-family: Arial, Helvetica, Tahoma, sans-serif;\"><i style=\"margin: 0px; padding: 0px;\"><font size=\"4\">Ubujura bwifashisha ikoranabuhanga, bukomeje gufata indi ntera, kugeza ubwo amabanki n’inzego za gisirikare zinjirirwa mu ibanga rikomeye n’ubwo hari ibigo bishinzwe ubwirinzi mu bijyanye n’ikoranabuhanga.</font></i></p><p style=\"margin-right: 0px; margin-bottom: 14px; margin-left: 0px; padding: 0px; color: rgb(102, 102, 102); font-family: Arial, Helvetica, Tahoma, sans-serif;\"><font size=\"4\">Mu myaka ishize nibwo ibigo nka Ikigo Symantec muri California na Kaspersky yo mu Burusiya byatangaje ko abajura mu by’ikoranabuhanga biyise “Strider” cyangwa “ProjectSauron” ; mu gihe cy’imyaka itanu bagabye ibitero byo kuneka amabanga y’ibihugu birimo u Burusiya, u Bushinwa, Iran, u Bubiligi na Suède.</font></p><p style=\"margin-right: 0px; margin-bottom: 14px; margin-left: 0px; padding: 0px; color: rgb(102, 102, 102); font-family: Arial, Helvetica, Tahoma, sans-serif;\"><font size=\"4\">Ikigo gitanga serivisi z’ubwirinzi bwa mudasobwa Kaspersky cyo mu Burusiya, giheruka gutangaza ko ibigo 30 byo muri ibyo bihugu byibasiwe birimo ibya Leta, ibigo by’ubushakashatsi, ibya gisirikare, ibitanga serivisi z’itumanaho n’ibigo by’imari.</font></p><p style=\"margin-right: 0px; margin-bottom: 14px; margin-left: 0px; padding: 0px; color: rgb(102, 102, 102); font-family: Arial, Helvetica, Tahoma, sans-serif;\"><font size=\"4\">Hari uburyo bwinshi abahanga mu by’ikoranabuhanga berekana ko aba bajura bifashisha kurusha ubundi, muri bwo hari :</font></p><p style=\"margin-right: 0px; margin-bottom: 14px; margin-left: 0px; padding: 0px; color: rgb(102, 102, 102); font-family: Arial, Helvetica, Tahoma, sans-serif;\"><strong style=\"margin: 0px; padding: 0px; font-weight: bold;\"><font size=\"4\">Internet y’ubuntu</font></strong></p><p style=\"margin-right: 0px; margin-bottom: 14px; margin-left: 0px; padding: 0px; color: rgb(102, 102, 102); font-family: Arial, Helvetica, Tahoma, sans-serif;\"><font size=\"4\">Ni henshi usanga mu duce duhuriramo abantu, iyo ucanye mudasobwa yawe cyangwa telefoni ibasha kwakira internet idakoresha umugozi [wireless], uhita ubonako hari internet y’ubuntu ushobora gutangira gukoresha udasabwe ijambo ry’ibanga.</font></p><p style=\"margin-right: 0px; margin-bottom: 14px; margin-left: 0px; padding: 0px; color: rgb(102, 102, 102); font-family: Arial, Helvetica, Tahoma, sans-serif;\"><img src=\"https://i.imgur.com/VR7tbWE.jpg\" width=\"422\"><font size=\"4\"><br></font></p><p style=\"margin-right: 0px; margin-bottom: 14px; margin-left: 0px; padding: 0px; color: rgb(102, 102, 102); font-family: Arial, Helvetica, Tahoma, sans-serif;\"><font size=\"4\">Iri ni irembo ryagutse ku ba Hackers, ku buryo iyo uri kuyikoresha biborohera kukwinjirira mu mabanga arinzwe mu buryo budahambaye, ndetse bakabasha kwiba imibare y’ibanga uba uri gukoresha hanyuma bakayifashisha mu mu nyungu zabo bwite.</font></p><p style=\"margin-right: 0px; margin-bottom: 14px; margin-left: 0px; padding: 0px; color: rgb(102, 102, 102); font-family: Arial, Helvetica, Tahoma, sans-serif;\"><font size=\"4\">Ubu nibwo buryo bworoshye kurusha ubundi bakoresha bifashishije igikoresho gisakaza internet y’ubuntu, Wireless Access Point, WAP.</font></p><p style=\"margin-right: 0px; margin-bottom: 14px; margin-left: 0px; padding: 0px; color: rgb(102, 102, 102); font-family: Arial, Helvetica, Tahoma, sans-serif;\"><font size=\"4\">Aha uzasanga biyitirira izina ry’aho abantu bagambiriwe bakunda guhurira, niba ari nk’ahafatirwa ikawa ya Maraba, ugasanga internet yabo bayise Maraba Free Wireless, ku buryo uhageze atajijinganya kuyihitamo.</font></p><p style=\"margin-right: 0px; margin-bottom: 14px; margin-left: 0px; padding: 0px; color: rgb(102, 102, 102); font-family: Arial, Helvetica, Tahoma, sans-serif;\"><strong style=\"margin: 0px; padding: 0px; font-weight: bold;\"><font size=\"4\">Kwifashisha ibintu bihishe</font></strong></p><p style=\"margin-right: 0px; margin-bottom: 14px; margin-left: 0px; padding: 0px; color: rgb(102, 102, 102); font-family: Arial, Helvetica, Tahoma, sans-serif;\"><font size=\"4\">Kuri iyi nshuro hari ubwo ujya ufungura email ukabona umuntu utazi yakoherereje akantu bakakubwira ngo ugakorere ‘download’ kugira ngo ukabone, rimwe na rimwe bakifashisha izina ry’umuntu muziranye nyamara we atazi n’uko byagenze.</font></p><p style=\"margin-right: 0px; margin-bottom: 14px; margin-left: 0px; padding: 0px; color: rgb(102, 102, 102); font-family: Arial, Helvetica, Tahoma, sans-serif;\"><img src=\"https://i.imgur.com/z8044mf.jpg\" width=\"422\"><font size=\"4\"><br></font></p><p style=\"margin-right: 0px; margin-bottom: 14px; margin-left: 0px; padding: 0px; color: rgb(102, 102, 102); font-family: Arial, Helvetica, Tahoma, sans-serif;\"><font size=\"4\">Uzabona agasa n’ifoto gaherwa n’ijambo GIF na JPG [ ku buryo ushobora gukeka ko ari ifoto kuko akenshi ariyo iba ifite bene iriya misusire (format)] cyangwa agaporogaramu gato gaherwa na .EXE, bagusabe kugakandamo kugira ngo ubashe kukabona. Aho bizagusaba kwitonda kuko iyo ugafunguye kinjiza imikorere muri mudasobwa yawe ishobora korohereza umu hackers kugera kubyo ubitse.</font></p><p style=\"margin-right: 0px; margin-bottom: 14px; margin-left: 0px; padding: 0px; color: rgb(102, 102, 102); font-family: Arial, Helvetica, Tahoma, sans-serif;\"><strong style=\"margin: 0px; padding: 0px; font-weight: bold;\"><font size=\"4\">Kugukurikirana bihagije</font></strong></p><p style=\"margin-right: 0px; margin-bottom: 14px; margin-left: 0px; padding: 0px; color: rgb(102, 102, 102); font-family: Arial, Helvetica, Tahoma, sans-serif;\"><font size=\"4\">Hari uburyo mudasobwa ibika ibintu ukunda gusoma cyane kuri internet cyangwa imbuga ukunda gusura, ibyo bita “cookies”, aba Hackers bakabyifashisha mu kukugenzura bifashishije izo mbuga ukunda gusura.</font></p><p style=\"margin-right: 0px; margin-bottom: 14px; margin-left: 0px; padding: 0px; color: rgb(102, 102, 102); font-family: Arial, Helvetica, Tahoma, sans-serif;\"><font size=\"4\">Niba uri nk’umugore ukunda kugurira imyenda ku ikoranabuhanga (Online shopping) uzatangira kubona amatangazo menshi akwamamazaho imyenda igezweho wagura, akaza yitura mu bindi uri kwisomera.</font></p><p style=\"margin-right: 0px; margin-bottom: 14px; margin-left: 0px; padding: 0px; color: rgb(102, 102, 102); font-family: Arial, Helvetica, Tahoma, sans-serif;\"><font size=\"4\">Hari ubwo uyafungura bagahita bakwinjirira mu ikoranabuhanga, bakiba amagambo y’ibanga iyo wagiye uyarekera kuri internet. Aha ni nk’aho ujya nko muri email, niba ukoresha nka Google Browser cyangwa Mozilla, ikakubaza niba ushaka kubikamo umubare w’ibanga ku buryo utazajya usabwa kuwandika uko ushatse kwinjiramo [Save password].</font></p><p style=\"margin-right: 0px; margin-bottom: 14px; margin-left: 0px; padding: 0px; color: rgb(102, 102, 102); font-family: Arial, Helvetica, Tahoma, sans-serif;\"><font size=\"4\">Aha bisaba ko niba ufite porogaramu ukoreramo ubushabitsi bwawe, abayigutunganyiriza bahora bayivugurura, cyane mu buryo bw’ubwirinzi.</font></p><p style=\"margin-right: 0px; margin-bottom: 14px; margin-left: 0px; padding: 0px; color: rgb(102, 102, 102); font-family: Arial, Helvetica, Tahoma, sans-serif;\"><strong style=\"margin: 0px; padding: 0px; font-weight: bold;\"><font size=\"4\">Kukubaza utubazo dutandukanye</font></strong></p><p style=\"margin-right: 0px; margin-bottom: 14px; margin-left: 0px; padding: 0px; color: rgb(102, 102, 102); font-family: Arial, Helvetica, Tahoma, sans-serif;\"><font size=\"4\">Ni kenshi uzabona ku mbuga zinyuranye bakuzanira igisa n’amatora cyangwa ubushakashatsi runaka, bagusaba kugira icyo uhitamo wowe ukabifata nko kwishimisha, rimwe na rimwe bakakubwira ngo ‘kanda aha ugwize amahirwe yo gutsindira…’ wabigerageza bati ‘urabanza wandike umubare w’ibanga, niba udusuye bwa mbere urasabwa kubanza gufunguza konti.’’</font></p><p style=\"margin-right: 0px; margin-bottom: 14px; margin-left: 0px; padding: 0px; color: rgb(102, 102, 102); font-family: Arial, Helvetica, Tahoma, sans-serif;\"><font size=\"4\">Mubibazo ugenda ubazwa, hari aho ushiduka watanze amakuru menshi akwerekeyeho arimo n’ay’ibanga wujuje mu ikoranabuhanga ryawe, ku buryo bayifashisha mugushakisha uburyo usanzwe winjira mu bikorwa byawe, bakagutera batyo.</font></p><p style=\"margin-right: 0px; margin-bottom: 14px; margin-left: 0px; padding: 0px; color: rgb(102, 102, 102); font-family: Arial, Helvetica, Tahoma, sans-serif;\"><font size=\"4\">Aha ho bizagusaba ko niba hari ahantu ugiye kuzuza, wifashisha umubare w’ibanga utandukanye ahantu henshi, ndetse ukirinda gusubiza ikintu gifite aho gihuriye n’andi makuru ubitse kugira ngo utivamo.</font></p><p style=\"margin-right: 0px; margin-bottom: 14px; margin-left: 0px; padding: 0px; color: rgb(102, 102, 102); font-family: Arial, Helvetica, Tahoma, sans-serif;\"><strong style=\"margin: 0px; padding: 0px; font-weight: bold;\"><font size=\"4\">Kwibwa umubare w’ibanga</font></strong></p><p style=\"margin-right: 0px; margin-bottom: 14px; margin-left: 0px; padding: 0px; color: rgb(102, 102, 102); font-family: Arial, Helvetica, Tahoma, sans-serif;\"><font size=\"4\">Iki nicyo kibazo gikomeye kuko niba ari nka porogaramu umuntu akoresha, ahita ayitakazaho uburenganzira bwose bwo kuyinjiramo, ku buryo umujura wayinjiyemo atwara ibyo ashatse adasize no kuba yakwangiza ubwirinzi bushobora gutuma wongera kuyisubirana mu buryo bworoshye.</font></p><p style=\"margin-right: 0px; margin-bottom: 14px; margin-left: 0px; padding: 0px; color: rgb(102, 102, 102); font-family: Arial, Helvetica, Tahoma, sans-serif;\"><font size=\"4\">Niho uzumva ngo ikoranabuhanga runaka ryashimuswe cyangwa uru rubuga rwa internet ruri mu maboko y’abagizi ba nabi.</font></p><p style=\"margin-right: 0px; margin-bottom: 14px; margin-left: 0px; padding: 0px; color: rgb(102, 102, 102); font-family: Arial, Helvetica, Tahoma, sans-serif;\"><strong style=\"margin: 0px; padding: 0px; font-weight: bold;\"><font size=\"4\">Bumwe mu bujura bukomeye bumaze kubaho</font></strong></p><p style=\"margin-right: 0px; margin-bottom: 14px; margin-left: 0px; padding: 0px; color: rgb(102, 102, 102); font-family: Arial, Helvetica, Tahoma, sans-serif;\"><font size=\"4\">Kugeza uyu munsi ubujura bufatwa nk’ubukomeye bwifashishijwe ikoranabuhanga mu mabanki, ni ubuheruka bwa miliyoni 650 z’ama-pound, ni ukuvuga agera kuri 672. 970. 230. 400 Frw, yatahuwe ko yibwe mu mabanki anyuranye ku Isi mu 2015.</font></p><p style=\"margin-right: 0px; margin-bottom: 14px; margin-left: 0px; padding: 0px; color: rgb(102, 102, 102); font-family: Arial, Helvetica, Tahoma, sans-serif;\"><font size=\"4\">Amakuru avuga ko amabanki yo mu Bwongereza yatakaje miliyoni nyinshi z’ama-pound, nyuma y’uko mu 2013 na 2014 abajura b’Abarusiya bashyiraga mu bikorwa uwo mugambi ukomeye wanyujijwe mu kuyobya amafaranga yahererekanywaga, ukaza gutahurwa bitinze ariko wari wamaze kwibasira ibigo by’imari bisaga 100.</font></p><p style=\"margin-right: 0px; margin-bottom: 14px; margin-left: 0px; padding: 0px; color: rgb(102, 102, 102); font-family: Arial, Helvetica, Tahoma, sans-serif;\"><font size=\"4\">Mu minsi ishize kandi nta wakwibagirwa igitero cyagabwe ku ruganda rukora amafilimi muri Hollywood [Uruganda rwa sinema muri Leta Zunze Ubumwe za Amerika], Sony Pictures Entertainment hakibwa amakuru asaga 100TB [soma: Telabayiti ijana], aho aba Hackers babinjiriye ndetse bakazimya ikoranabuhanga ryabo kuwa 24 Ugushyingo 2014.</font></p><p style=\"margin-right: 0px; margin-bottom: 14px; margin-left: 0px; padding: 0px; color: rgb(102, 102, 102); font-family: Arial, Helvetica, Tahoma, sans-serif;\"><font size=\"4\">Ni igitero cyagabwe nyuma ya filimi uru ruganda rwatunganyaga igaruka ku iyicwa rya Kim Jong un Perezida wa Korea ya Ruguru, igitero cyagabwe n’abantu biyise abarinzi b’amahoro, Guardians of Peace, “#GOP”.</font></p><p style=\"margin-right: 0px; margin-bottom: 14px; margin-left: 0px; padding: 0px; color: rgb(102, 102, 102); font-family: Arial, Helvetica, Tahoma, sans-serif;\"><font size=\"4\">Icyo gihe ku mashini zabo hagaragaye ho agahanga hariho n’ubutumwa buburira icyo kigo ko bashobora kumena “amabanga” akomeye kibitse, bituma umwe mu bayobozi bacyo Amy Pascal yegura.</font></p><p style=\"margin-right: 0px; margin-bottom: 14px; margin-left: 0px; padding: 0px; color: rgb(102, 102, 102); font-family: Arial, Helvetica, Tahoma, sans-serif;\"><font size=\"4\">Sony yibwiraga ko ari ikibazo cy’ikoranabuhanga ariko biza kugaragara ko kugikemura bishobora gufata hagati y’umunsi umwe n’ibyumweru bitatu, kugeza ubwo na FBI [Federal Bureau of Investigation : Ibiro bishinzwe iperereza muri Amerika] yabyinjiyemo igatangira iperereza.</font></p><p style=\"margin-right: 0px; margin-bottom: 14px; margin-left: 0px; padding: 0px; color: rgb(102, 102, 102); font-family: Arial, Helvetica, Tahoma, sans-serif;\"><font size=\"4\">Nyuma haje ubutumwa buvuga ngo “Mwitonde: Twarababuriye, ubu iyi ni intangiriro…Twamaze kubona amakuru yanyu yose yo mu kigo harimo amabanga yo ku rwego rwo hejuru.”</font></p><p style=\"margin-right: 0px; margin-bottom: 14px; margin-left: 0px; padding: 0px; color: rgb(102, 102, 102); font-family: Arial, Helvetica, Tahoma, sans-serif;\"><font size=\"4\">Icyo gitero byaje kuvugwa ko cyari gishyigikiwe na Korea ya Ruguru nubwo yo yabyitarukije ariko ishimangira ko uwabikoze wese yakoze “igikorwa nyacyo”.</font></p><p style=\"margin-right: 0px; margin-bottom: 14px; margin-left: 0px; padding: 0px; color: rgb(102, 102, 102); font-family: Arial, Helvetica, Tahoma, sans-serif;\"><font size=\"4\">Muri Gicurasi 2014 nabwo, ikigo cyo muri Amerika gikora ubucuruzi bwo kuri internet, eBay Inc. cyatangaje ko aba-Hackers bacyinjiriye bakajya mu makuru asaga miliyoni 145, ku buryo byanagize ingaruka ku ma konti abakiliya bifashisha ubwo buryo bari barafunguje.</font></p><p style=\"margin-right: 0px; margin-bottom: 14px; margin-left: 0px; padding: 0px; color: rgb(102, 102, 102); font-family: Arial, Helvetica, Tahoma, sans-serif;\"><font size=\"4\">Icyo kigo cyahise gisaba abakiliya bacyo kwihutira guhindura imibare y’ibanga bakoresha, kuko yari mu mabanga abo bajura bari bamaze amezi abiri biba.</font></p><p style=\"margin-right: 0px; margin-bottom: 14px; margin-left: 0px; padding: 0px; color: rgb(102, 102, 102); font-family: Arial, Helvetica, Tahoma, sans-serif;\"><font size=\"4\">Amakuru nk’aya kandi yagiye yibwa cyane n’abanyamakuru bo mu kigo Wikileaks, badahwema gushyira amabanga hanze ndetse abayobozi batandukanye bakisanga bagomba kuyasobanura cyangwa bagashaka ukundi babivuga.</font></p><p style=\"margin-right: 0px; margin-bottom: 14px; margin-left: 0px; padding: 0px; color: rgb(102, 102, 102); font-family: Arial, Helvetica, Tahoma, sans-serif;\"><font size=\"4\">Uwo byagizeho ingaruka n’uburyo nk’ubu ni Hillary Clinton igihe yiyamamarizaga kuyobora Leta Zunze Ubumwe za Amerika, ubutumwa bwe bwa emails buheruka gushyirwa hanze ko yakoreshaga konti ye bwite kandi ari mu kazi ka leta nk’Umunyamabanga ushinzwe ububanyi n’amahanga.</font></p>', '1590615445download (1).jpg', 'muhahe.com', 1040, 1, 'Hackers,Muhahe Ltd', 'Menya uko Uko aba Hackers bashobora kwinjira mu mabanga yawe nuko wabirinda.<br>', 'muhahe.com', '2020-05-27 19:37:25'),
(51, 9, 'Musanze: Umugabo Yakoresheje amayeri adasanzwe yo kwambara nk\'abagore ubundi ajya kwiba.', '<p><span style=\"color:#666666\"><span style=\"font-size:x-large\">Umugabo wo mu Murenge wa Nyange mu Karere ka Musanze, arakekwaho icyaha cy&rsquo;ubujura, aho ngo yafashwe amaze kwiba ibikoresho binyuranye, mu ijoro rishyira tariki 27 Gicurasi 2020 akaba yari yiyoberanyije mu myambaro y&rsquo;abagore.</span></span></p>\r\n\r\n<div>&nbsp;\r\n<div>\r\n<p style=\"margin-left:0px; margin-right:0px\"><span style=\"font-size:large\">Uwo mugabo ngo ubwo yamaraga gutobora inzu ya Twarayisenze Eugene wo mu Murenge wa Musanze mu Karere ka Musanze, yatwaye ibikoresho binyuranye birimo Televisiyo ( Flat TV), Radio, icyuma cyifashishwa mu kuyungurura amajwi, Ibitenge bitatu, dekoderi n&rsquo;ibindi.</span></p>\r\n\r\n<p style=\"margin-left:0px; margin-right:0px\"><span style=\"font-size:large\">Uwo mugabo wagaragaye yambaye neza nk&#39;abagore aho byari bigoranye kwemeza niba koko ari umugabo aho yari yambaye ibitenge hamwe n&#39;iribaya ryabyo, imitwe yatetse ntiyamuhiriye kuko yahise afatwa atabwa muri yombi, aho ubu afungiye kuri Polisi sitasiyo ya Musanze.</span></p>\r\n\r\n<p style=\"margin-left:0px; margin-right:0px\"><span style=\"font-size:large\">Umunyamabanga Nshingwabikorwa w&rsquo;Umurenge wa Musanze, Dushimire Jean, yatangarije Kigali Today ko uwo mugabo yafatiwe mu muhanda wa kaburimbo ari mu bandi bagenzi nyuma yo guhabwa amakuru n&rsquo;umuturage wamuketsemo kuba atari umugore nubwo yari yambaye nk&rsquo;abagore.</span></p>\r\n\r\n<p style=\"margin-left:0px; margin-right:0px\"><span style=\"font-size:large\">Ati &quot;Ubwo twashakishaga umuntu umaze gutobora inzu y&rsquo;umuturage wari umaze kwibwa aho inzu bari bayitoboye, umuturage yaduhaye amakuru avuga ko ahuye n&rsquo;umuturage uri kugenda mu bakore wambaye ibitenge ariko umeze nk&rsquo;umugabo, ageze kuri kaburimbo, mwihuse mwamufata.</span></p>\r\n\r\n<p style=\"margin-left:0px; margin-right:0px\"><span style=\"font-size:large\">Gitifu Dushimire ngo yahise afata imodoka arirukanka aho yanyuze ku itsinda ry&rsquo;abagore bari muri kaburimbo, ahagarika imodoka arabafotora barebye basanga koko uwo muntu wari ukenyeye ibitenge ni umugabo. Nibwo bahise bamushyira imbere ajya kubereka aho yabyibye.</span></p>\r\n\r\n<p style=\"margin-left:0px; margin-right:0px\"><span style=\"font-size:large\">Ati &quot;Tukimara kumufata twamubajije impamvu yambaye ibyo bitenge kandi ari umugabo adusubiza ko amayeri ari gukoreshwa muri iyi minsi ari ukwambara nk&rsquo;abagore mu buryo bwo kwirinda ko babakeka. Ngo ubundi bambara imyambaro y&rsquo;abagore kugira ngo abanyezamu bo mu ngo n&rsquo;abanyerondo bakeke ko ari abagore bavuye gucuruza bakererewe, ni uko yatubwiye.&quot;</span></p>\r\n\r\n<p style=\"margin-left:0px; margin-right:0px\"><span style=\"font-size:large\">Gitifu Dushimire yongeye agira ati &quot;Twamushyize imbere tumusaba kujya kutwereka aho yibye ibintu yikoreye nibwo yatujyanye ku mugabo wari umaze kudutabaza avuga ko bamwibye, dusanga koko iyo nzu yayitoboye yibamo ibyo bikoresho byose yari yikoreye birimo Flat, ibitenge, Radio, amplificateur, dekoderi, CD ariko tumusangana indangamuntu itariye, dusanga ni iy&rsquo;umuntu witwa Karamira wo mu Murenge wa Rushashi mu Karere ka Rulindo&quot;.</span></p>\r\n\r\n<p style=\"margin-left:0px; margin-right:0px\"><span style=\"font-size:large\">Uwo wafashwe yavuze ko ibyo yari amaze kwiba yari agiye kubigurisha mu mujyi wa Musanze n&rsquo;abo bafatanya kwiba. Yahise ashyikirizwa Urwego rw&rsquo;Ubugenzacyaha (RIB) Sitasiyo ya Cyuve ari na ho ari mu gihe ari gukurikiranwa kuri ibyo byaha akekwaho.</span></p>\r\n\r\n<p style=\"margin-left:0px; margin-right:0px\"><span style=\"font-size:large\">Ibyo uwo mugabo yakoze ni igikorwa cyanenzwe na Kamanzi Axelle, Umuyobozi wungirije ushinzwe imibereho myiza y&rsquo;abaturage mu Karere ka Musanze, aho yasabye abaturage gukura amaboko mu mifuka bagakora, bakarya ibyo bavunikiye.</span></p>\r\n\r\n<p style=\"margin-left:0px; margin-right:0px\"><span style=\"font-size:large\">Uwo muyobozi yaburiye abakomeje gucura imigambi y&rsquo;ubujura, avuga ko bitazabahira kuko inzego z&rsquo;umutekano n&rsquo;iz&rsquo;ubuyobozi ziri maso, avuga ko uzagerageza kwiha iby&rsquo;abandi hari amategeko amuhana.</span></p>\r\n</div>\r\n</div>', '1592809706a man.JPG', 'kigalitoday', 1331, 1, 'Muhahe Ltd', '<p>Musanze: Umugabo Yakoresheje amayeri adasanzwe yo kwambara nk&#39;abagore ubundi ajya kwiba.</p>', 'muhahe.com', '2020-05-27 20:03:43'),
(53, 11, 'RURA: Ibiciro by’ingendo zambukiranya intara n’umujyi wa Kigali byiyongereye cyane kubera Covid-19', '<p class=\"MsoNormal\" style=\"mso-margin-top-alt:auto;mso-margin-bottom-alt:auto;\r\nline-height:normal\"><b><span style=\"font-size:15.0pt;mso-bidi-font-size:12.0pt;\r\nfont-family:\" times=\"\" new=\"\" roman\",\"serif\";mso-fareast-font-family:\"times=\"\" roman\"\"=\"\">Hashize\r\namezi asaga 2 ingendo zihuza intara n’umujyi wa Kigali zarahagaritswe kubera\r\nCovid-19, Kuri uyu wa Gatatu tariki ya 03 Kamena 2020,Abagenzi ndetse n’abamotari\r\nbazindutse iya rubika berekeza mu Ntara zitandukanye ukuyemo Akarere ka Rubavu\r\nn’aka Rusizi hatemerewe gukora ingendo rusange.<o:p></o:p></span></b></p>\r\n\r\n<p class=\"MsoNormal\" style=\"margin-bottom:0cm;margin-bottom:.0001pt;line-height:\r\nnormal\"><span style=\"font-size:12.0pt;font-family:\" times=\"\" new=\"\" roman\",\"serif\";=\"\" mso-fareast-font-family:\"times=\"\" roman\"\"=\"\"><o:p>&nbsp;</o:p></span></p>\r\n\r\n<p>Byari ibyishimo bidasanzwe k\'ubagenzi bakunze gukoresha moto kuko bamwe bavuga ko zibafasha kugera aho bagiye vuba bitabasabye gutonda imirongo nk\'uko bigenda igihe bateze imodoka rusange,abamotari bishimiye gusubira mu muhanda nyuma y’igihe cyari gishize ibinyabiziga byabo biparitse mu rugo kubera amabwiriza yo kwirinda icyorezo cya\r\nCOVID-19 aho bavuga ko batari borohewe n\'ubukene.<o:p></o:p></p>\r\n\r\n<p>Nubwo bimeze bityo,abagenzi bakoze ingendo hirya no hino mu ntara z’igihugu\r\nuretse Rusizi na Rubavu bakubitanye n’izamuka rihambaye ry’ibiciro by’ingendo.<o:p></o:p></p><p><img src=\"https://i.imgur.com/zWRBvaC.jpg\" width=\"422\"><br></p><p><img src=\"https://i.imgur.com/MIuczu9.jpg\" width=\"422\"><br></p><p><br></p><p><img src=\"https://i.imgur.com/mDhzqoS.jpg\" width=\"422\"><br></p><p><img src=\"https://i.imgur.com/Rw8LD4j.jpg\" width=\"422\"><br></p><p>Mu minsi ishize ubwo imodoka zitwara abagenzi zemerewe gukora hagati muntara\r\nRURA yatangaje ko izamuka ry’ikiguzi cy’urugendo cyazamutse bitewe n’uko\r\nimodoka zirimo gutwara abantu bake ugereranije nuko zari zisanzwe zikora mbere\r\nya COVID-19 aho zirimo gutwara 1/2 cyabo zatwaraga.<o:p></o:p></p><p><br></p>', '1591225848rura.JPG', 'ijabiro.com', 1778, 1, 'COVID-19', 'RURA: Ibiciro by’ingendo zambukiranya intara n’umujyi wa Kigali byiyongereye cyane kubera Covid-19<br>', 'Muhahe.com', '2020-06-03 21:10:48');
INSERT INTO `blogs` (`id`, `category_id`, `title`, `details`, `photo`, `source`, `views`, `status`, `meta_tag`, `meta_description`, `tags`, `created_at`) VALUES
(54, 11, 'Dore ibyo ugomba kumenya mugihe ukoresha Gas mu rugo iwawe.', '<h1>&nbsp;</h1>\r\n\r\n<p style=\"text-align:justify\"><strong><span style=\"font-size:16.0pt\">Mu rwego rwo gukomeza kubungabunga ibidukikije, Guverinoma y&rsquo;u Rwanda ikomeje gukangurira Abanyarwanda gukoresha Gas</span></strong><span style=\"font-size:16pt\">,ni nyuma yaho bitacyemewe kwinjiza amakara mu mugi wa kigali</span><strong><span style=\"font-size:16.0pt\">,aho gukoresha amakara cyangwa inkwi mu gihe bateka, kuko bigira ingaruka ku bidukikije n&rsquo;amashyamba n&rsquo;ibindi.</span></strong></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:14.0pt\">Ariko n&rsquo;ubwo&nbsp; gahoro gahoro abantu bagenda basobanukirwa n&rsquo;ibyiza byo gukoresha Gas, abenshi baracyafite impungenge z&rsquo;uburyo&nbsp; ziturikira mu mazu ndetse rimwe na rimwe zigatera impanuka zikomeye ndetse n&rsquo;ibiciro bikiri hejuru, ugereranije n&rsquo;amakara abandi bakaba bacyibaza ukuntu bazajya bakoresha Gas gusa mu guteka ibiryo byose harimo n&#39;ibimara igihe kinini bitetswe(ibishyimbo byumye) kandi bitwara Gas nyinshi.</span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:14.0pt\">Gukoresha Gas ntibigoye, gusa bisaba kuba ufite ubumenyi bw&rsquo;ibanze mu kuyikoresha kugirango itaguteza ibibazo mu gihe uyikoresha.</span></p>\r\n\r\n<p style=\"text-align:justify\"><strong><span style=\"font-size:14.0pt\"><a href=\"https://rwandanews24.com/2020/05/30/dore-ibyo-ugomba-kumenya-mu-gihe-uteka-ku-mashyiga-ya-gas/\">Dore ibyo ugomba kumenya mu gihe uteka ku mashyiga ya Gas.</a></span></strong><span style=\"font-size:14pt\">&nbsp;</span></p>\r\n\r\n<p style=\"margin-left:15pt; margin-right:15pt; text-align:justify\"><!--[if !supportLists]--><span style=\"color:#555555; font-family:Symbol; font-size:10.0pt\">&middot;<span style=\"font-size:7pt\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span><!--[endif]--><span style=\"font-size:14.0pt\">Gas ni umwuka ariko uzirana n&rsquo;umuriro. Iyo gas ihuye n&rsquo;umuriro habaho kwaka byihuse kandi ntibiterwa n&rsquo;ingano y&rsquo;umuriro wabonetse, umuriro uwo ariwo wose ushobora guteza impanuka ya Gas. Bityo rero mbere y&rsquo;uko ucana ishyiga ryawe rya gas, banza wizere neza nib nta Gas iri gusohoka kuburyo ihura n&rsquo;umuriro. Ntabwo ushobora kuyoberwa niba gas iri gusohoha kuko igihe cyose winjiye ahantu iteretse wumva impumuro idasanzwe muri ako gace. Igihe rero uzabyumva uzabe uretse gucana umuriro. Hari kandi agakoresho kagurishwa ku isoko, gashobora kukumenyesha niba Gas yawe iri gusohoka. Aka gakoresho Karasona mu ijwi ritandukanye bitewe n&rsquo;ingano ya Gas iri gusohoka.</span></p>\r\n\r\n<p style=\"margin-left:15pt; margin-right:15pt; text-align:justify\"><!--[if !supportLists]--><span style=\"color:#555555; font-family:Symbol; font-size:10.0pt\">&middot;<span style=\"font-size:7pt\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span><!--[endif]--><span style=\"font-size:14.0pt\">Igihe Gas yawe yashizemo uvuye kugura indi, si byiza guhita uyicana ako kanya ukimara kuyizana. Jya ubanza uyitereke akanya ituze kuko baba bayizanye bayicugusa bikaba byatuma itomboka mu gihe uhise uyicana.</span></p>\r\n\r\n<p style=\"margin-left:15pt; margin-right:15pt; text-align:justify\"><!--[if !supportLists]--><span style=\"color:#555555; font-family:Symbol; font-size:10.0pt\">&middot;<span style=\"font-size:7pt\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span><!--[endif]--><span style=\"font-size:14.0pt\">Sibyiza gusiga ucanye Gas ngo wigendere ahantu kure tugirwa inama yo kuba hafi yahoo dutekeye kuri Gas.</span></p>\r\n\r\n<p style=\"margin-left:15pt; margin-right:15pt; text-align:justify\"><!--[if !supportLists]--><span style=\"color:#555555; font-family:Symbol; font-size:10.0pt\">&middot;<span style=\"font-size:7pt\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span><!--[endif]--><span style=\"font-size:14.0pt\">Sibyiza kuvugira kuri telefoni cyangwa kugira ibindi birangaza igihe utetse kuri Gas.</span></p>\r\n\r\n<p style=\"margin-left:15pt; margin-right:15pt; text-align:justify\"><!--[if !supportLists]--><span style=\"color:#555555; font-family:Symbol; font-size:10.0pt\">&middot;<span style=\"font-size:7pt\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span><!--[endif]--><span style=\"font-size:14.0pt\">Sibyiza gutegeza abana Gas ngo bateke nta muntu mukuru uhari.</span></p>\r\n\r\n<p style=\"margin-left:15pt; margin-right:15pt; text-align:justify\"><!--[if !supportLists]--><span style=\"color:#555555; font-family:Symbol; font-size:10.0pt\">&middot;<span style=\"font-size:7pt\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span><!--[endif]--><span style=\"font-size:14.0pt\">Irinde ko ibishashi bya Gas birenga impande z&rsquo;isafuriya mu gihe utetse ugomba kugabanya umuriro ugakoresha muke.</span></p>\r\n\r\n<p style=\"margin-left:15pt; margin-right:15pt; text-align:justify\"><!--[if !supportLists]--><span style=\"color:#555555; font-family:Symbol; font-size:10.0pt\">&middot;<span style=\"font-size:7pt\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span><!--[endif]--><span style=\"font-size:14.0pt\">Buri gihe uragirwa inama yo gukoresha igitambaro gikomeye igihe uterura isafuriya ishyushye kuri Gas.</span></p>\r\n\r\n<p style=\"margin-left:15pt; margin-right:15pt; text-align:justify\"><!--[if !supportLists]--><span style=\"color:#555555; font-family:Symbol; font-size:10.0pt\">&middot;<span style=\"font-size:7pt\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span><!--[endif]--><span style=\"font-size:14.0pt\">Si byiza gushyira ibiryo mu mavuta ahiye kandi Gas iri kwaka. Mbere yo gushyira ibiryo mu mavuta banza uzimye Gas.</span></p>\r\n\r\n<p style=\"margin-left:15pt; margin-right:15pt; text-align:justify\"><!--[if !supportLists]--><span style=\"color:#555555; font-family:Symbol; font-size:10.0pt\">&middot;<span style=\"font-size:7pt\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span><!--[endif]--><span style=\"font-size:14.0pt\">Uragirwa inama yo gufungura amadirishya y&rsquo;aho utekera mu gihe cyose amashyiga ya Gas ari kwaka.</span></p>\r\n\r\n<p style=\"margin-left:15pt; margin-right:15pt; text-align:justify\"><!--[if !supportLists]--><span style=\"color:#555555; font-family:Symbol; font-size:10.0pt\">&middot;<span style=\"font-size:7pt\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span><!--[endif]--><span style=\"font-size:14.0pt\">Niba ukoresha Gas ifite amashyiga 2,3+, mbere y&rsquo;uko uhindura icupa banza urebe niba amashyiga adacanye, kandi mu gihe urangije guteka banza uzimye ishyiga ubundi wibuke gufunga Gas ku icupa.</span></p>\r\n\r\n<p style=\"margin-left:15pt; margin-right:15pt; text-align:justify\"><!--[if !supportLists]--><span style=\"color:#555555; font-family:Symbol; font-size:10.0pt\">&middot;<span style=\"font-size:7pt\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span><!--[endif]--><span style=\"font-size:14.0pt\">Niba ukoresha Gas, uragirwa inama yo kuba ufite kizimyamwoto hafi kandi ufite n&rsquo;ahantu hizewe umuntu ashobora guhungira inkongi y&rsquo;umuriro mu gikoni cyawe.</span></p>\r\n\r\n<p style=\"margin-left:15pt; margin-right:15pt; text-align:justify\"><!--[if !supportLists]--><span style=\"color:#555555; font-family:Symbol; font-size:10.0pt\">&middot;<span style=\"font-size:7pt\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span><!--[endif]--><span style=\"font-size:14.0pt\">Amazi ashobora gutuma umuriro usakara mu buryo bwihuse, rero niba ubona umuriro watse ihutire gufunga ishyiga, maze upfuke ibishashi ukoresheje umufuniko w&rsquo;isafuriya niba bigushobokera.</span></p>\r\n\r\n<p style=\"margin-left:15pt; margin-right:15pt; text-align:justify\"><!--[if !supportLists]--><span style=\"color:#555555; font-family:Symbol; font-size:10.0pt\">&middot;<span style=\"font-size:7pt\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span><!--[endif]--><span style=\"font-size:14.0pt\">Igihe Gas yawe yagize ikibazo urasabwa guhamagara ababizi bakagufasha kugikemura, si byiza ku byikorera niba nta bumenyi ubifitemo.</span></p>\r\n\r\n<p style=\"margin-left:0px; margin-right:0px; text-align:start\">&nbsp;</p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:14.0pt\">&nbsp;</span></p>', '1592809423cooking-with-gas.jpg', 'muhahe.com', 1386, 1, 'Muhahe.com,gutekesha gas', '<p>Dore ibyo ugomba kumenya mugihe ukoresha Gas mu rugo iwawe.</p>', 'Muhahe.com,kigaligas', '2020-06-05 03:42:17'),
(57, 11, 'MINALOC yashyizeho amabwiriza agenga umuhango wo gusezerana mu nsengero', '<p><em><strong><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:11pt\"><span style=\"font-size:18.0pt\">Nyuma y&#39;aho Inama y&rsquo;Abaminisitiri yateranye tariki ya 16 Kamena 2020 yemeje ko imihango yo gushyingirwa mu nsengero ikomorewe, ariko ikitabirwa n&rsquo;abantu batarenze 30. Iyo nama yasabye Minisiteri y&rsquo;Ubutegetsi bw&rsquo;Igihugu kuzatanga amabwiriza arambuye kuri iyi ngingo, ayo mabwiriza akaba yashyizwe ahagaragara kuri uyu wa 18 Kamena 2020.ayo mabwiriza asobanura birambuye uko abazashaka gukora igikorwa cyo gusezerana mu nsengero bagomba kwitwara kugira hakomeze kwirinda icyorezo cya koronavirusi.</span></span></span></strong></em></p>\r\n\r\n<p>Mu ngingo z&rsquo;ingenzi ziyakubiyemo harimo ko aho ubera hakwiye kuba hujuje ibyangombwa, hagasukurwa mbere na nyuma y&rsquo;umuhango wo gusezeranya, hanashyizweho uburyo bwo kwirinda Coronavirus bworohereza abantu kubahiriza amabwiriza arimo gukaraba neza intoki no guhana intera.</p>\r\n\r\n<p>Iyubahirizwa ry&rsquo;aya mabwiriza rizajya rikurikiranwa n&rsquo;abafite inyubako zakira ibi birori, abayobozi b&rsquo;inzego z&rsquo;ibanze n&rsquo;abigisha b&rsquo;idini/itorero.</p>\r\n\r\n<p><img alt=\"-\" height=\"11\" src=\"https://igihe.com/local/cache-vignettes/L8xH11/puce-32883.gif?1564353591\" width=\"8\" />&nbsp;&nbsp;<strong>Amabwiriza agomba kubahirizwa:</strong></p>\r\n\r\n<p>1. Imiryango ishingiye ku myemerere igomba kugeza mu nyandiko ingengabihe y&rsquo;abazasezerana ku nzego z&rsquo;ibanze (Umurenge) nibura iminsi ibiri mbere yuko umuhango uba.</p>\r\n\r\n<p>2. Gusezerana imbere y&rsquo;Imana bishobora gukorerwa mu nsengero zujuje ibisabwa, izindi nyubako zakira abantu (hotel, amahema, sale) n&rsquo;ahandi hantu hafunguye.</p>\r\n\r\n<p>3. Usezeranya agomba kuba ahagarariye umuryango ushingiye ku myemerere wemewe.</p>\r\n\r\n<p><strong>4. Insengero, inyubako n&rsquo;ahandi hantu hasezeranirwa hagomba kuba hujuje ibi bikurikira:</strong></p>\r\n\r\n<p>a. Inyubako isengerwamo igomba kuba isanzwe yemerewe gusengerwamo hashingiwe ku mabwiriza agenga inyubako zisengerwamo.</p>\r\n\r\n<p>b. Gusukura inyubako mbere na nyuma y&rsquo;umuhango wo gusezeranya hakoreshejwe amazi meza n&rsquo;isabune.</p>\r\n\r\n<p>c. Gushyiraho uburyo bwo gukaraba intoki [kandagira ukarabe n&rsquo;amazi meza n&rsquo;isabune cyangwa imiti isukura intoki/hand sanitizer].</p>\r\n\r\n<p>d. Kwambara agapfukamunwa neza ku bantu bose baje mu muhango wo gusezerana.</p>\r\n\r\n<p>e. Gusiga nibura intera ya metero ebyiri hagati y&rsquo;umuntu n&rsquo;undi uretse hagati y&rsquo;abasezerana.</p>\r\n\r\n<p><strong>5. Mu gikorwa cyo gusezeranya</strong></p>\r\n\r\n<p>a. Gusuhuzanya bahana amaboko no guhoberana cyangwa guhobera abageni birabujijwe keretse hagati y&rsquo;abasezerana.</p>\r\n\r\n<p>b. Guhererekanya indangururamajwi [microphone] n&rsquo;ibindi bikoresho (urugero: Ibitabo by&rsquo;indirimbo, Bibiliya, Korowani, ibyuma bya Muzika) ntibyemewe.</p>\r\n\r\n<p>c. Gutanga amaturo bigomba gukorwa hifashishijwe ikoranabuhanga (mobile money services, money transfer,&hellip;)</p>\r\n\r\n<p>d. Gusengera abantu barambikwaho ibiganza birabujijwe.</p>\r\n\r\n<p>e. Kugira ngo duhamye ingamba zo kwirinda icyorezo cya Coronavirus turasaba ko igikorwa cyo gusezeranya nyirizina kitarenza isaha imwe.</p>\r\n\r\n<p><strong>6. Ibirori byo kwakira abatumiwe (reception)</strong></p>\r\n\r\n<p>a. Umubare w&rsquo;abitabira uyu muhango ntugomba kurenga abantu 30 kandi hakubahirizwa amabwiriza yose yo kwirinda icyorezo cya Coronavirus.</p>\r\n\r\n<p>b. Umuhango ugomba kubera ahantu habugenewe kandi hafunguye; mu gihe bikorewe muri hoteli nabwo abawitabiriye ntibagomba kurenga 30 kandi hakubahirizwa amabwiriza ajyanye no kwirinda Coronavirus.</p>\r\n\r\n<p><strong>7. Iyubahirizwa ry&rsquo;amabwiriza</strong></p>\r\n\r\n<p>a. Abayobozi b&rsquo;inzego z&rsquo;ibanze n&rsquo;izindi nzego bafatanyije mu kwirinda Coronavirus no gukumira ikwirakwira ryayo, bagomba gukurikirana ishyirwa mu bikorwa ry&rsquo;aya mabwiriza.</p>\r\n\r\n<p>b. Abafite inyubako zakira ibi birori, abayobozi n&rsquo;abigisha b&rsquo;idini/itorero ryabasezeranyije bagomba gukurikirana iyubahirizwa ry&rsquo;aya mabwiriza.</p>\r\n\r\n<figure class=\"easyimage easyimage-full\"><img alt=\"\" src=\"blob:https://muhahe.com/b56e5d27-5720-4a3a-92fd-ec7cbbf5a6fb\" width=\"393\" />\r\n<figcaption></figcaption>\r\n</figure>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<figure class=\"easyimage easyimage-full\"><img alt=\"\" src=\"blob:https://muhahe.com/f070f533-70b3-4ea3-a58e-efe1ac791ff2\" width=\"387\" />\r\n<figcaption></figcaption>\r\n</figure>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<figure class=\"easyimage easyimage-full\"><img alt=\"\" src=\"blob:https://muhahe.com/967746a8-ff8c-4e9e-b0cc-401b176f5b4f\" width=\"374\" />\r\n<figcaption></figcaption>\r\n</figure>\r\n\r\n<p>&nbsp;</p>', '1592809322logosi.JPG', 'Igihe', 1021, 1, 'insengero,minaloc,covid-19', '<p>MINALOC yashyizeho amabwiriza agenga umuhango wo gusezerana mu nsengero</p>', 'muhahe.com', '2020-06-19 07:48:49'),
(58, 7, '​Menya icyatumye umuhanzi Akon afata umwanzuro wo gushyiraho ifaranga rye yise Akoin.', '<p><strong><em><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\">&nbsp;<span style=\"font-size:12.0pt\">Umuhanzi <span style=\"background-color:#ecf0f1\">Aliaume Damala Badara<span style=\"background-color:#ecf0f1\"> </span>Akon Thiam</span> uzwi cyane ku izina rya <span style=\"background-color:#ecf0f1\">Akon</span>, yahishuye ko yigeze kuva iwabo muri S&eacute;n&eacute;gal agiye mu Bufaransa, akamara igihe kinini abitse umuba w&rsquo;amafaranga y&rsquo;ama-CFA akoreshwa mu gihugu cye kuko yari yabuze aho ayavunjisha.</span></span></span></em></strong></p>\r\n\r\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\">Uyu muhanzi yavuze ko ubwo yari avuye mu gihugu cye mu myaka mike ishize, yageze i Paris ajya aho bavunjishiriza amafaranga, maze ngo uwamwakiriye aramubwira ati &ldquo;muratwihanganira ayo ntituyakira&rdquo;.</span></span></span></p>\r\n\r\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\">Ati &ldquo;Naribajije nti ibi ni ibiki?&rdquo; Yakomeje avuga ko mbere y&rsquo;uko akora urugendo rwe atari yigeze abona umwanya wo kuvunjisha amafaranga yari afite ngo ayavane mu ma-CFA ku buryo yabuze icyo ayakoresha.</span></span></span></p>\r\n\r\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\">Yakomeje agira ati &ldquo;Byamfunguye amaso. Byasembuye imbaraga zo kuvuga ngo tugomba kugira ifaranga ryacu muri Africa kuko n&#39;asanzwe akoreshwa usanga agenda igira utubazo dutandukanye aho mu myaka iri mbere wasanga azaba atagikoreshwa. Sinitaye ku cyo bizasaba ariko tugomba kubikemura.&rdquo;</span></span></span></p>\r\n\r\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\">Ibi byatumye Akon ahita atangiza ibikorwa byo gushyiraho ifaranga ry&rsquo;ikoranabuhanga rizitwa Akoin rikazakoreshwa ku ikubitiro mu mujyi mushya ari kubaka mu gihugu cye uzaba witwa Akon City.</span></span></span></p>\r\n\r\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\">Ikoranabuhanga rimaze gutera imbere ku Isi ku rwego rw&rsquo;aho abantu barikoresheje bakarema amafaranga adafite igihugu ashingiyeho kandi ntashobore kugaragara cyangwa ngo afatwe mu ntoki, ahererekanywa mu buryo bw&rsquo;ikoranabuhanga rizwi nka &lsquo;Cryptocurrency&rsquo;. Mu yamenyekanye cyane harimo irizwi na benshi rya &lsquo;Bitcoin&rsquo;.</span></span></span></p>\r\n\r\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\">Ifaranga rikozwe muri ubu buryo rikoreshwa hifashishijwe ikoranabuhanga rizwi nka &lsquo;Blockchain&rsquo; mu ihererekanwa ryayo kuri internet.</span></span></span></p>\r\n\r\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\">Byitezwe ko Akoin ari ifaranga rishobora kujya hanze mu kwezi gutaha ku buryo ryakoreshwa, igitekerezo ni uko ryayobokwa no mu bihugu byose bya Afurika.</span></span></span></p>\r\n\r\n<figure class=\"easyimage easyimage-full\"><img alt=\"\" src=\"blob:https://muhahe.com/60359f8e-8a48-4eae-8950-e2cb08105aea\" width=\"1000\" />\r\n<figcaption>Igishushanyo mbonera cy&#39;umugi wa Akon City</figcaption>\r\n</figure>\r\n\r\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\">Akon City, umujyi witiriwe Akon, icyiciro cya mbere byitezwe ko kizasozwa mu 2023. Kizaba kigizwe n&rsquo;iyubakwa ry&rsquo;imihanda, ibitaro bya Hamptons Hospital, inzu yo guhahiramo izaba yitwa Hamptons Mall, sitasiyo ya Polisi, icyanya cyo gukusanyirizamo imyanda, ikigo cy&rsquo;amashuri ndetse n&rsquo;urugomero rw&rsquo;amashanyarazi.</span></span></span></p>\r\n\r\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\">Icyiciro cya kabiri cyo byitezwe ko kizarangira mu 2029 gihuza ibikorwa by&rsquo;ubucuruzi hifashishijwe ifaranga rya AKOIN. Kizaba kirimo Pariki, Stade, Kaminuza n&rsquo;igice cyahariwe inganda.</span></span></span></p>\r\n\r\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\">​</span></span></span></p>', '1592809371images (1).jpg', 'IGIHE', 880, 1, 'CRYPTOCURRENCY,AKOIN,AKON,IFARANGA', '<p><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\">​Menya icyatumye umuhanzi Akon afata umwanzuro wo gushyiraho ifaranga rye yise Akoin.</span></span></span></p>', 'CYPTOCURRENCY', '2020-06-21 20:18:18'),
(59, 11, 'Dore ahantu 10 nyaburanga ku isi ariko hanateye ubwoba hasurwa n\'abihebye nabo bashaka kwiyahura (AMAFOTO)', '<p><span style=\"font-size:18px\"><em><strong>Kuri iyi si dutuyeho hari ahantu heza cyane hanezeza buri wese utarahagera kuhakandagiza ibirenge bye, mu bitekerezo byawe hari ahantu utekereza ko uhageze byaba ari nk&rsquo;inzozi zisohoye, ibyo niba ariko bimeze kuri wowe ntugire ngo ni ibyawe gusa kuko buri umwe muri twe arabigira. Ariko nubwo aho hantu hahari hari n&rsquo;ahandi kuri iyi si ya Rurema hateye ubwoba ku buryo umenye ibyaho utakwemera no gukandagiza akarenge hafi yaho cyangwa ngo ugire umuntu inama yo kuhajya.</strong></em></span></p>\r\n\r\n<p>Muhahe.com twaguteguriye ahantu kuri iyi si hateye ubwoba cyane ku buryo nta muntu utekereza neza wagira ibitekerezo byo gupfa kujyayo uretse gusa uwumva yarihebye. Kuri uru rutonde rwacu turahera ku mwanya wa 10 tujya ku mwanya wa mbere w&rsquo;ahantu ku isi hateye ubwoba.</p>\r\n\r\n<p><strong>10. Death Valley, USA</strong></p>\r\n\r\n<figure class=\"easyimage easyimage-full\"><img alt=\"\" src=\"blob:https://muhahe.com/d20134ea-1319-4597-818c-7e23935ea15e\" width=\"1500\" />\r\n<figcaption></figcaption>\r\n</figure>\r\n\r\n<p>Death Valley bivuga ikibaya cy&rsquo;urupfu, aha ni muri Leta Zunze Ubumwe za Amerika, n&rsquo;izina ryaho ubwaryo risobanura ho gato uko haba hameze, aha hazwiho ko ariho hantu ha mbere hagira ubushyuhe bukabije karemano kuri iyi si nzima kuko ubushyuhe bwaho bugera kuri dogere Selisiyusi 56.7 zose. Aka gace katwaye ubuzima bw&rsquo;abantu benshi. Iyo ugeze muri aka gace utangazwa no kubona amabuye agenda ntawuyasunitse. Mu mwaka wa 1915 ni bwo itsinda ry&rsquo;abahanga ryagerageje gushaka igituma amabuye yo muri aka gace agenda, gusa barashobewe.bwaho budasanzwe.</p>\r\n\r\n<p><strong>9.</strong>Aokigahara</p>\r\n\r\n<figure class=\"easyimage easyimage-full\"><img alt=\"\" src=\"blob:https://muhahe.com/668e1a84-9e80-4c73-b98b-56b3b3a2fcf2\" width=\"1440\" />\r\n<figcaption></figcaption>\r\n</figure>\r\n\r\n<p>Aka ni agace kanditse amateka ku isi ubu ni ko ka kabiri kamaze gutwara ubuzima bw&rsquo;abantu benshi ku isi kuko gatwara abarenga 500 buri mwaka. Aka gace karangwa n&rsquo;imyuka mibi ndetse n&rsquo;abazimu kagizwe n&rsquo;ishyamba rya hegitali 3500 rihererereye ku gasongero k&rsquo;umusozi witwa &lsquo;fuji&rsquo;.</p>\r\n\r\n<p>8.<strong>The Danakil Desert, Eritrea</strong></p>\r\n\r\n<figure class=\"easyimage easyimage-full\"><img alt=\"\" src=\"blob:https://muhahe.com/dd21791a-08fd-4a36-a533-24e8c5cf6c80\" width=\"702\" />\r\n<figcaption></figcaption>\r\n</figure>\r\n\r\n<figure class=\"easyimage easyimage-full\"><img alt=\"\" src=\"blob:https://muhahe.com/66fd4419-1949-43ea-a1ad-a9b310737be9\" width=\"702\" />\r\n<figcaption></figcaption>\r\n</figure>\r\n\r\n<p>Niba washakaga gusura ibihugu byose bya Afrika sinkubujije ariko nugera muri Erithrea uzabaze ahari ubutayu bwa Danakil kugira ngo nuhagera uzahitondere bikomeye, aha harashyuha bikomeye kuko hagira ubushyuhe bugera kuri Dogere Selisiyusi 50. Icyo ntigikomeye kurusha kuba hafite ibirunga byinshi bihuzuye kandi bikaba birekura imyuka mibi cyane ku buzima bw&rsquo;ikiremwamuntu. Nubwo hameze hatya ntihabuza abantu kuhasura ariko nabo baba bazi neza ko baba bashyize ubuzima bwabo mu kaga. Ariko nubwo bahasura kirazira kikaziririzwa kuhagera uri wenyine utari kumwe nushinzwe kukuyobora akwereka aho utagomba kurenga bitewe n&rsquo;ukuntu hateye ubwoba.</p>\r\n\r\n<p>7.<strong>Sinabung Volcano, Indonesia</strong></p>\r\n\r\n<figure class=\"easyimage easyimage-full\"><img alt=\"\" src=\"blob:https://muhahe.com/1ffb14db-d4d5-4165-9357-a050f8f155a4\" width=\"702\" />\r\n<figcaption></figcaption>\r\n</figure>\r\n\r\n<figure class=\"easyimage easyimage-full\"><img alt=\"\" src=\"blob:https://muhahe.com/c734c88b-b0fc-4b14-97a0-e47f8778750c\" width=\"702\" />\r\n<figcaption></figcaption>\r\n</figure>\r\n\r\n<p>Iki ni ikirunga giherereye muri Indonesia kikaba kiri neza mu butayu bwa Sumatra. Kwitwa ikirunga ntago bikigira ahantu hateye ubwoba kuko kuri iyi si hari ibirunga byinshi cyane ahubwo aho iki gitandukaniye n&rsquo;ibindi ni uko cyo kiruka kenshi gashoboka kandi kikarekura imyuka ihumanya yangiza abantu.</p>\r\n\r\n<p>Nyuma yo kugira abantu batagira ingano imfubyi, abapfakazi, abakene n&rsquo;ibindi kubera kubamaraho abantu n&rsquo;ibintu ntago cyiteguye guhagarara, mu myaka itanu ishize cyamaze abantu batuye mu mijyi yegereye ubu butayu kubera kuruka inshuro nyinshi noneho muri uyu mwaka mu kwezi kwa kabiri cyakoze ibyo benshi mu bagize amahirwe yo gusigarana ubuzima batazibagirwa aho cyazamuye amabuye manini n&rsquo;amato n&rsquo;imyotsi mibi yangiza abantu mu burebure bugera kuri metero 2500 bikamanukira abantu batagira ingano, ntiwamenya ibyo kizakora ejo. Aha ntiwatekereza kujya kuharuhukira kereka ushaka iruhuko ridashira.</p>\r\n\r\n<p>6.<strong>Lha Da Queimada Grande, Brazil</strong></p>\r\n\r\n<figure class=\"easyimage easyimage-full\"><img alt=\"\" src=\"blob:https://muhahe.com/e8b72f02-6f41-42c2-8ec7-eace830e8649\" width=\"702\" />\r\n<figcaption></figcaption>\r\n</figure>\r\n\r\n<figure class=\"easyimage easyimage-full\"><img alt=\"\" src=\"blob:https://muhahe.com/7bcc563e-b7e8-49d9-8222-90113796826d\" width=\"702\" />\r\n<figcaption></figcaption>\r\n</figure>\r\n\r\n<p>Iki ni ikirwa kiri mu gihugu cya Brazil, wongeye kwitegereza iyo foto iri haruguru urabona ko Atari igiti gifite amabara abiri ahubwo ari inzoka iri mu giti, ahahafatwa nk&rsquo;ahantu hateye ubwoba ha mbere ku isi ibi si ukwivugira kuko impamvu zumvikana, aha niho hari inzoka nyinshi zifite ubumara buteye ubwoba harimo izitwa Bothrops ari nazo zifatwa nk&rsquo;izigira ubumara bukomeye kurusha izindi ku isi.</p>\r\n\r\n<p>Hari inzoka nyinshi ku buryo hari inzoka eshanu kuri metero kare imwe, ntibishoboka ko wagenda ngo utere intambwe ebyiri udakandagiye imwe murizo. Ahandi hantu hateye ubwoba uhajyana n&rsquo;umuntu ukuyobora cg ukahamara igihe gito ariko aha ho nta muntu numwe wemerewe kuhagera niyo wavuga ko wagombowe inshuro igihumbi. Hateye ubwoba kurusha uko uri kubitekereza.</p>\r\n\r\n<p>5.<strong>Madidi National Park, Bolivia</strong></p>\r\n\r\n<figure class=\"easyimage easyimage-full\"><img alt=\"\" src=\"blob:https://muhahe.com/e809f288-3f09-4072-ac37-e3f97923281f\" width=\"702\" />\r\n<figcaption></figcaption>\r\n</figure>\r\n\r\n<figure class=\"easyimage easyimage-full\"><img alt=\"\" src=\"blob:https://muhahe.com/a4de9233-2666-4fd0-818e-eea04ac69aa8\" width=\"702\" />\r\n<figcaption></figcaption>\r\n</figure>\r\n\r\n<p>4<strong>.North Sentinel Island</strong></p>\r\n\r\n<figure class=\"easyimage easyimage-full\"><img alt=\"\" src=\"blob:https://muhahe.com/14eea19e-590d-4cd9-99c3-9d7526702be1\" width=\"201\" />\r\n<figcaption></figcaption>\r\n</figure>\r\n\r\n<figure class=\"easyimage easyimage-full\"><img alt=\"\" src=\"blob:https://muhahe.com/80783f5c-f33c-4e01-86c9-326891d77ea8\" width=\"1280\" />\r\n<figcaption></figcaption>\r\n</figure>\r\n\r\n<p>3.<strong>Lake Natron, Tanzania</strong></p>\r\n\r\n<figure class=\"easyimage easyimage-full\"><img alt=\"\" src=\"blob:https://muhahe.com/21217365-816c-445b-aa51-844d7e5e4b79\" width=\"702\" />\r\n<figcaption></figcaption>\r\n</figure>\r\n\r\n<figure class=\"easyimage easyimage-full\"><img alt=\"\" src=\"blob:https://muhahe.com/27b3f12b-4a05-4e61-8b62-bcc74af5de78\" width=\"702\" />\r\n<figcaption></figcaption>\r\n</figure>\r\n\r\n<p>Uyu ni umugezi uba hano hirya mu gihugu cy&rsquo;abaturanyi cya Tanzaniya, wasoma Tanzania ukagira ngo ni ahandi hantu hatabaho, hoyaa ahubwo ni aho hafi pe. Ni abantu bake bahita bemera ko uyu ari umugezi bitewe n&rsquo;ukuntu ugaragara ariko gutyo ubibona ku ifoto ninako uhegereye wabona bimeze, ngo uyu mugezi rero ni iki kidasanzwe ufite kiwutera kuba ahantu habi cyane ku isi dutuyeho?</p>\r\n\r\n<p>Umunyu wo muri uyu mugezi ufite uburozi butemerera igihumeka na kimwe kuwubamo, guturuka ku bantu, amatungo ndetse n&rsquo;ibiti nta na kimwe urebera ijisho kuko uhita wica vuba na bangu, kuwogamo kirazira kikaziririzwa kuko umwuka wonyine wo muri ayo mazi utakwemerera kuryoherwa no koga. Aho kwicwa n&rsquo;aya mazi wakwicwa n&rsquo;inyota.</p>\r\n\r\n<p>2.<strong>Grand Canyon, Arizona (muri Amerika)</strong></p>\r\n\r\n<figure class=\"easyimage easyimage-full\"><img alt=\"\" src=\"blob:https://muhahe.com/caf83dee-b6b8-4130-a567-4eca66da1e21\" width=\"702\" />\r\n<figcaption></figcaption>\r\n</figure>\r\n\r\n<figure class=\"easyimage easyimage-full\"><img alt=\"\" src=\"blob:https://muhahe.com/64f951c0-67a6-43d8-a200-a7960a6e0ba9\" width=\"702\" />\r\n<figcaption></figcaption>\r\n</figure>\r\n\r\n<p>Grand Canyon ni muri Leta Zunze Ubumwe za Amerika muri Leta ya Arizona, aha uhabonye wagira ngo ni ahantu heza ho gutemberera cyangwa ho kwifotoreza nkuko bamwe bajya babigenza iyo bageze ahantu hadasanzwe, ariko hano hantu hateye ubwoba kuko iyo uri aha hantu uba usabwa gutera ikirenge ahantu habi ugahita ugenda, gupfa biba bikwegereye cyane kuko ikosa ryose wahakorera ari uguhita upfa, aha niho hantu ha kabiri ku isi hiyahurira abantu benshi, impamvu bahajya irasobanutse, ntawajya gushakaamazi mu Nyanja ngo ayabure kuko inyanja nka kindi ifite nkayo, naha rero urupfu rwose si ugushakisha ruba ruri aho hafi.</p>\r\n\r\n<p><strong>1. Mount Washington, muri Amerika</strong></p>\r\n\r\n<figure class=\"easyimage easyimage-full\"><img alt=\"\" src=\"blob:https://muhahe.com/534dc145-a73e-4334-a11f-6cac391cee35\" width=\"702\" />\r\n<figcaption></figcaption>\r\n</figure>\r\n\r\n<figure class=\"easyimage easyimage-full\"><img alt=\"\" src=\"blob:https://muhahe.com/b9679064-6f1c-4920-b7cc-039faf2d230c\" width=\"702\" />\r\n<figcaption></figcaption>\r\n</figure>\r\n\r\n<p>Uyu ni umusozi uri muri Leta Zunze ubumwe za Amerika muri Washington, uyu musozi ntusanzwe kuko niho hantu hejuru hagira imiyaga yihuta cyane kuri iyi si, iyo uri hejuru cyane aho umusozi urangira ushobora no guhuhwa n&rsquo;umuyaga ugenda 327km mu isaha, ubaye ufite ubushobozi bro guhangara uyu muyaga ntago bihagije ngo ube wajya kuri uyu musozi kuko hari ubukonje buteye ubwoba bujya bugera muri Degree -40 hakanagwa urubura rutagira akagero ibyo bigatuma haba ahantu hateye ubwoba.</p>\r\n\r\n<p>Umuntu wakandagiye kuri uyu musozi yemerewe kuvuga ko yageze ku gasongero ka Everest (umusozi muremure ku isi nzima) kuko uko uri kuri uyu musozi ari hejuru ari nako uri ku Everest yaba ameze ariko bikaba bitandukaniye ku buryo hateye kuko kuri uyu musozi ari ahantu hateye ubwoba u kigero cyo hejuru.</p>\r\n\r\n<p>Hari intonde zitandukanye uzasanga zikorwa z&rsquo;ahantu habi cyane ndetse hanateye ubwoba ikiremwamuntu kuhakandagira gusa uru nirwo rutonde ntakuka rw&rsquo;ahantu 10 ku isi hateye ubwoba hajya gusa abihebye bashaka kwiyahura nkuko bihurizwaho n&rsquo;ibinyamakuru bitandukanye.</p>', '1592816836logd.JPG', 'Umubavu', 1133, 1, 'muhahe ltd', '<p>Dore ahantu 10 ku isi nyaburanga ariko hateye ubwoba hajya gusa abihebye nabo bashaka kwiyahura (Amafoto)</p>', 'muhahe.com,Muhahe LTD', '2020-06-22 07:07:16'),
(60, 9, 'Trump: Bitunguranye mu gikorwa cyo kwamamaza Trump cyitabiriwe n\'abantu bake cyane kubari bitezwe.', '<p><span style=\"font-size:18px\"><em><strong>Iki gikorwa cyo&nbsp;kwamamaza Perezida Donald Trump cyatangiye ku mugaragaro ku wa gatandatu&nbsp;hari hitezwe abantu benshi ko bagomba kwitabira icyo gikorwa nkuko Bwana Trump, yari yatangaje ko igikorwa cye cya mbere cyo kwiyamamaza kizazamo abantu nibura miliyoni.</strong></em></span></p>\r\n\r\n<p><span style=\"font-size:12pt\"><span style=\"font-size:14.0pt\">Gusa yatunguwe nuko byaje kugenda kuko aho cyabereye muri stade ijyamo abantu 19,000 iri mu mujyi wa Tulsa, hari hateguwe kuburyo no hanze hajya abantu benshi cyane. Gusa hanze ntihakoreshejwe kuko n&#39;imbere bari bakeya cyane.<strong> </strong></span></span></p>\r\n\r\n<p><span style=\"font-size:12pt\"><span style=\"font-size:14.0pt\">Urubyiruko rwinshi rutarageza ku myaka 20 rwafasha amatike mbere ariko rudafite gahunda yo kujya muri uko kwiyamamaza, rugamije gusa ko imyanya izaba irimo ubusa.</span></span></p>\r\n\r\n<p><span style=\"font-size:12pt\"><span style=\"font-size:14.0pt\">Steve Schmidt wahoze mu ishyaka ry&#39;abarepubulikani ariko ubu unenga Bwana Trump, avuga ko urubyiruko henshi muri Amerika rwasabye amatike rudafite gahunda yo kwitabira.</span></span></p>\r\n\r\n<p><span style=\"font-size:12pt\"><span style=\"font-size:14.0pt\">Avuga ko umukobwa we w&#39;imyaka 16 hamwe n&#39;inshuti ze bafashe amatike abarirwa mu &quot;magana&quot;.</span></span></p>\r\n\r\n<p><span style=\"font-size:12pt\"><span style=\"font-size:14.0pt\">Hari abandi babyeyi nabo basubije Bwana Schmidt bavuga ko abana babo nabo bakoze nk&#39;ibi.</span></span></p>\r\n\r\n<p><span style=\"font-size:12pt\"><span style=\"font-size:14.0pt\">Gusa uruhande rwa Trump ruvuga ko ubusanzwe ruhora rwiteguye ibikorwa nk&#39;ibi kandi ko imyigaragambyo n&#39;ibitangazamakuru ari byo byatumye hari benshi batitabira, ko atari abafashe amatike babashuka ko bazaza.</span></span></p>\r\n\r\n<p><span style=\"font-size:12pt\"><span style=\"font-size:14.0pt\">Urwego rushinzwe kuzimya umuriro muri Tulsa ruvuga ko iki gikorwa cyajemo abantu 6,000 gusa ariko abo ku ruhande rwa Trump rurabihakana rw&rsquo;ivuye inyuma aho ruvuga ko haje benshi barenga aba.</span></span></p>\r\n\r\n<figure class=\"easyimage easyimage-full\"><img alt=\"\" src=\"blob:https://muhahe.com/6fcb9feb-4007-4185-b6d2-4ffb3a5a9b4a\" width=\"800\" />\r\n<figcaption></figcaption>\r\n</figure>\r\n\r\n<p><span style=\"font-size:12pt\"><span style=\"font-size:14.0pt\">Bwana Trump yatangiye avuga uti &quot;hanze hari abantu babi cyane bari gukora ibintu bibi&quot;</span></span></p>\r\n\r\n<p><span style=\"font-size:12pt\"><span style=\"font-size:14.0pt\">Ntabwo bizwi neza umubare w&#39;amatike ibihumbi amagana wafashwe n&#39;abantu batari bwitabire, gusa video yashyizwe kuri Tik-Tok tariki 12 z&#39;uku kwezi isaba abantu gufata amatike y&#39;ubuntu igamije ko hazaba imyanya myinshi irimo ubusa yagize abayikunze barenga 700,000.</span></span></p>\r\n\r\n<p><span style=\"font-size:12pt\"><span style=\"font-size:14.0pt\">Uruhande rushinzwe ibikorwa byo kwamamaza Perezida Donald Trump rurahakana ko ubukangurambaga bwo ku rubuga rwa Tik-Tok n&#39;abafana b&#39;itsinda rya muzika K-pop ari bo batumye igikorwa cye cyo kwiyamamaza ku wa gatandatu i Oklahoma kizamo abantu bacyeya.</span></span></p>\r\n\r\n<p><span style=\"font-size:12pt\"><span style=\"font-size:14.0pt\">Iyi video yashyizwe kuri Tik-Tok hakiri kare kuko itariki y&#39;ukwiyamamaza kwa Trump yari 19 z&#39;uku kwezi.</span></span></p>\r\n\r\n<p><span style=\"font-size:12pt\"><span style=\"font-size:14.0pt\">Iyi tariki yari yateye benshi uburakari kuko ihura n&#39;umunsi wa Juneteenth abirabura muri Amerika bizihizaho kurangira kw&#39;ibinyejana by&#39;ubucakara.</span></span></p>\r\n\r\n<p><span style=\"font-size:12pt\"><span style=\"font-size:14.0pt\">Aho byabereye naho, Tulsa, hakaba ahantu habereye ubwicanyi bukomeye ku birabura mu mateka ya Amerika.ibi bikaba ari muri bimwe abantu batunga agatoki byaba byarateye abantu batandukanye kutitabira iki gikorwa nyuma y&rsquo;aho Trump atangarije amagambo Atari meza k&rsquo;ubantu bari mu myigaragambyo bamagana ubwicanyi bw&rsquo;abirabura.</span></span></p>\r\n\r\n<p>&nbsp;</p>', '1592822465loggg.JPG', 'BBC', 1035, 1, 'TRUMP,TRUMP\'S COMPAIGN', '<p>Trump: Bitunguranye mu gikorwa cyo kumwamamaza ntabwo cyitabiriwe nk&#39;uko byari byiteze.</p>', 'Muhahe.com', '2020-06-22 08:21:25'),
(61, 8, 'KTRN Rwanda yasobanuye impamvu murandasi (internet) ya 4G Unlimited ikoreshwa muri smart phone  igiye gukurwaho burundu.', '<p><span style=\"font-size:11pt\"><span style=\"background-color:white\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:14.5pt\"><span style=\"background-color:white\"><span style=\"color:#191919\">Hashize iminsi ibigo byagurishaga internet ya 4G Unlimited biha ubutumwa abakiliya babyo ko bigiye guhagarika kugurisha iyo Internet muri za telefone zabo.</span></span></span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:12pt\"><span style=\"background-color:white\"><span style=\"font-size:13.5pt\"><span style=\"color:#262626\">Tariki 8 Kamena Ikigo cy&rsquo;Itumanaho MTN Rwanda cyatangaje ko guhera ku wa 1 Nyakanga kizahagarika kugurisha internet ya 4G Unlimited umuntu yajyaga agura agakoresha ikarangira mu gihe runaka.</span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:12pt\"><span style=\"background-color:white\"><span style=\"font-size:13.5pt\"><span style=\"color:#262626\">4G Unlimited ni internet yatangwaga mu gihe runaka nk&rsquo;icyumweru cyangwa ukwezi, umukiliya akishyura ubwo akaba azi ko icyo cyumweru cyangwa ukwezi azabimara ataguze indi.</span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:12pt\"><span style=\"background-color:white\"><span style=\"font-size:13.5pt\"><span style=\"color:#262626\">Ikigo cy&rsquo;abanya-Koreya, KTRN Rwanda ari nacyo rukumbi cyemerewe kuranguza internet ya 4G mu Rwanda, cyatangaje ko guhera tariki 1 Nyakanga 2020 internet ya 4G Unlimited muri za telefone itazongera kuboneka ku isoko.</span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:12pt\"><span style=\"background-color:white\"><span style=\"font-size:13.5pt\"><span style=\"color:#262626\">Umuyobozi Mukuru ushinzwe ikoranabuhanga n&rsquo;itumanaho muri KTRN Rwanda, Elijah Iragaba, yatangaje ko izo mpinduka zigamije gukemura ikibazo cy&rsquo;ireme rya internet batangaga ku bakoresha telefone zigezweho.</span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:12pt\"><span style=\"background-color:white\"><span style=\"font-size:13.5pt\"><span style=\"color:#262626\">Yavuze ko ubusanzwe internet ya 4G Unlimited yatangwaga muri za telefone nubwo yari ihendutse, mu ikorwa ryayo hari imwe mu mipaka yashyizweho ku bijyanye n&rsquo;uburyo yihuta mu gihe habayeho kuyisangira n&rsquo;abandi (tethering) cyangwa kuyivana kuri telefone ngo ikoreshwe no kuri mudasobwa.</span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:12pt\"><span style=\"background-color:white\"><span style=\"font-size:13.5pt\"><span style=\"color:#262626\">Iragaba yavuze ko iyo abakiliya bayifashishaga mu bindi bitari telefone, yagendaga gahoro bigatuma babyinubira.</span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:12pt\"><span style=\"background-color:white\"><span style=\"font-size:13.5pt\"><span style=\"color:#262626\">Ati &ldquo; (4G unlimited) yakorewe gukoreshwa muri za telefone ariko hari abantu bajyaga bayisangiza ngo bayikoreshe no ku bindi bikoresho nka mudasobwa zo mu biro bigatuma babona internet ifite ireme ritari ryiza kuko hari ibyo iyo internet itagomba kurenza. Byatumaga rero binuba.&rdquo;</span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:12pt\"><span style=\"background-color:white\"><span style=\"font-size:13.5pt\"><span style=\"color:#262626\">Iragaba yijeje ko ubu internet ya 4G isanzwe yavuguruwe irimo ibyo abakiliya bakeneye byose kandi ihendutse kurushaho.</span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:12pt\"><span style=\"background-color:white\"><span style=\"font-size:13.5pt\"><span style=\"color:#262626\">Icyakora, ibyo byumvikanisha ko ubu umukiliya azajya agura internet ya 4G agahabwa ingano runaka bitewe n&rsquo;amafaranga yishyuye, igashira bitewe n&rsquo;uburyo yayikoresheje. Bivuze ko ushobora kugura internet ya 5000 Frw, wayikoresha gahoro ikaba yamara igihe kinini, wayikoresha cyane igashira vuba ariko umuvuduko wo ugakomeza kuba wa wundi.</span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:12pt\"><span style=\"background-color:white\"><span style=\"font-size:13.5pt\"><span style=\"color:#262626\">Umuyobozi ushinzwe Ikoranabuhanga mu Rwego Ngenzuramikorere (RURA), Gahungu Charles, yavuze ko KTRN yabamenyesheje ukwinuba abakiliya bari bafite, bakavuga ko uko byari bimeze mbere byicaga isura ya internet ya 4G muri rusange.</span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:12pt\"><span style=\"background-color:white\"><span style=\"font-size:13.5pt\"><span style=\"color:#262626\">Internet ya 4G Unlimited yakoreshwaga ni iyo mu bwoko bwa &lsquo;Speed-based&rsquo; igenda ku muvuduko umwe bitewe n&rsquo;igihe umukiliya yahawe kuyimarana, ubu hasigaye Internet yo mu buryo bwa &lsquo;volume-based&rsquo; ishira bitewe n&rsquo;uko yakoreshejwe.</span></span></span></span></p>', '15929228974g.jpg', 'IGIHE', 906, 1, 'online shopping,shopping rwanda,e-commerce rwanda,muhahe,delivery,rwanda', '<p>MTRN Rwanda yasobanuye impamvu murandasi (internet) ya 4G Unlimited ikoreshwa muri smart phone &nbsp;igiye gukurwaho burundu.</p>', 'muhahe.com', '2020-06-23 12:34:57'),
(63, 8, 'udukoryo 10 utaruzi wakoresha mu gihe uri gushaka ikintu kuri google ', '<p><span style=\"font-size:20px\"><em><strong><span style=\"font-family:Times New Roman,Times,serif\">Kumenya gukoresha Google Search ntabwo ari ibintu bigoye, ntanubwo bisaba kubyiga mu ishuri kuko Google ubwayo ikorohereza kubona amahitamo y&#39;ibintu bigera mu bihumbi mugihe uyibajije ijambo rimwe. Ibi bituma benshi bibwira ko ntakindi kirenze kuri ibi, Google nayo ntabwo yivuna ikwereka uko uyikoresha,aho ukoze ikosa ikagerageza kugukosora.</span></strong></em></span></p>\r\n\r\n<p><span style=\"font-size:18px\"><span style=\"font-family:Times New Roman,Times,serif\">Nyamara hari uburyo google yashyizeho ushobora kwifashisha ukaba wabona icyo ushaka byoroshye mugihe ubaye ubukoresheje, Aha twagukoreye urutonde rw&#39;uburyo&nbsp;10 wakwifashisha.</span></span></p>\r\n\r\n<div><span style=\"font-size:20px\"><span style=\"font-family:Times New Roman,Times,serif\"><strong>1. Koresha utwuguruzo n&rsquo;utwugarizo (quotes) maze ushakishe interuro uko yakabaye yose.</strong></span></span></div>\r\n\r\n<p><span style=\"font-size:18px\"><span style=\"font-family:Times New Roman,Times,serif\">Ubusanzwe iyo ushakishije interuro kuri Google, Google ikuzanira ibisubizo (results) birimo amagambo agize iyo nteruro buri jambo ukwaryo. Ariko iyo ukoresheje utwugarizo ikuzanira ibisubizo birimo iyo nteruro gusa.</span></span></p>\r\n\r\n<figure class=\"easyimage easyimage-full\"><img alt=\"\" src=\"blob:https://muhahe.com/c63aa389-3c34-4ea2-bdac-78f15a0714ca\" width=\"924\" />\r\n<figcaption></figcaption>\r\n</figure>\r\n\r\n<div><span style=\"font-size:20px\"><span style=\"font-family:Times New Roman,Times,serif\"><strong>2. Koreshesha akanyenyeri (*) mu twugarizo ku ijambo ushidikanyaho.</strong></span></span></div>\r\n\r\n<p><span style=\"font-size:18px\"><span style=\"font-family:Times New Roman,Times,serif\">Wenda tuvuge ko urimo gushaka lyrics z&rsquo;indirimbo, ariko ukaba ushidikanya ku ijambo runaka, ushobora gukoresha akanyenyeri kuri iryo jambo ku buryo Google yarisimbuza irindi jambo mu gihe iryo ritabonetse.</span></span></p>\r\n\r\n<figure class=\"easyimage easyimage-full\"><img alt=\"\" src=\"blob:https://muhahe.com/d1bc540d-59f4-466e-9383-9647319824d0\" width=\"768\" />\r\n<figcaption></figcaption>\r\n</figure>\r\n\r\n<div><span style=\"font-size:20px\"><span style=\"font-family:Times New Roman,Times,serif\"><strong>3. Koresha akamenyetso ko gukuramo (-) ku magambo utifuza ko agaragara mu byo uyibajije.</strong></span></span></div>\r\n\r\n<p><span style=\"font-size:18px\"><span style=\"font-family:Times New Roman,Times,serif\">Tuvuge wenda ko urimo gushaka ikintu runaka, Google igakomeza ikuzanira ibyo udakeneye, ushobora gukoresha tire (-) imbere y&rsquo;ijambo udashaka ko igarura. (Urugero: urutonde rw&#39;ibigo by&#39;amashuri -kaminuza).</span></span></p>\r\n\r\n<figure class=\"easyimage easyimage-full\"><img alt=\"\" src=\"blob:https://muhahe.com/ab87f77e-45df-489e-98b7-e858b56bbd3c\" width=\"909\" />\r\n<figcaption></figcaption>\r\n</figure>\r\n\r\n<div><span style=\"font-size:20px\"><span style=\"font-family:Times New Roman,Times,serif\"><strong>4. Shakisha kuri website imwe gusa.</strong></span></span></div>\r\n\r\n<p><span style=\"font-size:18px\"><span style=\"font-family:Times New Roman,Times,serif\">Ushobora gukoresha &ldquo;site:&rdquo;, ukabaza Google kugushakira kuri iyo website gusa. Niba ushaka kubona inkuru Muhahe.com yanditse zirimo ijambo &ldquo;indirimbo&rdquo; ushobora kwandika: &ldquo;indirimbo site:Muhahe.com&rdquo;.</span></span></p>\r\n\r\n<figure class=\"easyimage easyimage-full\"><img alt=\"\" src=\"blob:https://muhahe.com/9f5e4727-0354-4b27-a16d-9de513b369e9\" width=\"860\" />\r\n<figcaption></figcaption>\r\n</figure>\r\n\r\n<div><span style=\"font-size:20px\"><span style=\"font-family:Times New Roman,Times,serif\"><strong>5. Koresha &ldquo;define&rdquo; maze ubone ubusobanuro bw&rsquo;amagambo.</strong></span></span></div>\r\n\r\n<p><span style=\"font-size:18px\"><span style=\"font-family:Times New Roman,Times,serif\">Urugero: (define umunebwe)&nbsp;</span></span></p>\r\n\r\n<figure class=\"easyimage easyimage-full\"><img alt=\"\" src=\"blob:https://muhahe.com/33ebbb7a-d023-4de4-b94e-eb86310cf78a\" width=\"876\" />\r\n<figcaption></figcaption>\r\n</figure>\r\n\r\n<div><span style=\"font-size:20px\"><span style=\"font-family:Times New Roman,Times,serif\"><strong>6. Shakisha urubuga (site) ruya gukora&nbsp;kimwe n&rsquo;urwo usanzwe uzi.</strong></span></span></div>\r\n\r\n<p><span style=\"font-size:18px\"><span style=\"font-family:Times New Roman,Times,serif\">Ushaka nko kugereranya ibiciro cg se kureba site nziza wakoresha ikora bimwe n&rsquo;indi usanzwe uzi, ushobora gukoresha &ldquo;<strong>related:</strong>website&rdquo;. (urugero: related:whatsapp.com)</span></span></p>\r\n\r\n<div><span style=\"font-size:20px\"><span style=\"font-family:Times New Roman,Times,serif\"><strong>7. Google ishobora kugukorera imibare.</strong></span></span></div>\r\n\r\n<p><span style=\"font-size:18px\"><span style=\"font-family:Times New Roman,Times,serif\">Google ushobora kuyikoresha nka calculatrice cyangwa&nbsp;se ukayibaza ibibazo bijyanye na science. (urugero: 5 * 4 + 100, avogadro&rsquo;s constant) ushobora kandi no kwandika ijambo &ldquo;<strong>calculator</strong>&rdquo; maze ikaguha calculator ukoresha.</span></span></p>\r\n\r\n<figure class=\"easyimage easyimage-full\"><img alt=\"\" src=\"blob:https://muhahe.com/c534af55-46ad-48b0-8a3b-19ecbe83d93f\" width=\"898\" />\r\n<figcaption></figcaption>\r\n</figure>\r\n\r\n<div><span style=\"font-size:20px\"><span style=\"font-family:Times New Roman,Times,serif\"><strong>8. Kuvunja amafaranga no guhindura ingero z&rsquo;uburebure.</strong></span></span></div>\r\n\r\n<p><span style=\"font-size:18px\"><span style=\"font-family:Times New Roman,Times,serif\">Wari uziko ushobora kubaza google idorari 1 rihagaze angahe cg se uko mile imwe ingana mu birometero. (urugero: 1 USD to RWF, 1 mile in km).</span></span></p>\r\n\r\n<div><span style=\"font-size:20px\"><span style=\"font-family:Times New Roman,Times,serif\"><strong>9. Shaka ubwoko runaka bwa file (fichier).</strong></span></span></div>\r\n\r\n<p><span style=\"font-size:18px\"><span style=\"font-family:Times New Roman,Times,serif\">Ushobora kubwira google kukuzanira&nbsp;<strong>pdf</strong>&nbsp;gusa cg ubundi bwoko bwa fichier wifuza, ukoresheje&nbsp;<strong>filetype</strong>. (urugero: amategeko y&#39;umuhanda filetype:pdf )&nbsp;</span></span></p>\r\n\r\n<div><span style=\"font-size:20px\"><span style=\"font-family:Times New Roman,Times,serif\"><strong>10. Gukora amakosa mu myandikire ntacyo bitwaye.</strong></span></span></div>\r\n\r\n<p><span style=\"font-size:18px\"><span style=\"font-family:Times New Roman,Times,serif\">Google ikoresha technique yitwa &ldquo;Fuzzy Search&rdquo; ku buryo nubwo ijambo ryaba ryanditse nabi igerageza gushaka irindi byenda gusa. Ntukagire ikibazo mu gihe utazi neza uko ijambo ryandikwa.</span></span></p>\r\n\r\n<p><span style=\"font-size:18px\"><span style=\"font-family:Times New Roman,Times,serif\">urugero:nushakakisha wanditse&nbsp;&ldquo;Nver Gna Gve Yo Up&rdquo; Google yo izahita ibona ko washakaga kwandika&nbsp;&ldquo;Never Gonna Give You Up.&rdquo;</span></span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>', '1593002857Google Search Tricks.png', 'Google', 1033, 1, 'TRICKS,GOOGLE SEARCH', '<p>Udukoryo 10 Utaruzi Wakoresha Mu Gihe Uri Gushaka Ikintu Kuri Google</p>', NULL, '2020-06-24 10:47:37');
INSERT INTO `blogs` (`id`, `category_id`, `title`, `details`, `photo`, `source`, `views`, `status`, `meta_tag`, `meta_description`, `tags`, `created_at`) VALUES
(65, 7, 'Menya urubuga waguriraho ndetse ukanacururizaho kuri murandasi ruriguca ibintu.', '<p><span style=\"font-size:20px\"><strong><span style=\"font-family:Calibri,sans-serif\">Aho icyorezo cya coronavirus kigaragariye mu bihugu bitandukanye ku isi ubuzima bwarahindutse kuburyo bugaragara,ibikorwa byinshi bisimbuzwa ikoranabuhanga aho usanga abantu bose bakorera akazi mungo zabo,bagasengera murugo ndetse n&rsquo;aho ingendo zemewe hakifashishwa uburyo bwo kwishyura hakoreshejwe ikoranabuhanga (cashless), hamwe nibindi byinshi bitandukanye mu buryo bwo kwirinda gukwirakwiza COVID-19.</span></strong></span></p>\r\n\r\n<p><span style=\"font-size:13.0pt\">Nubwo kugeza ubu ingendo hirya no hino mu ntara hamwe n&rsquo;umugi wa Kigali zemewe, ariko abayobozi bakomeza kutugira inama yo kudakora ingendo zitari ngombwa ndetse aho bishoboka&nbsp; ukaba wagura icyo ushaka wifashishije murandasi (online ordering) bakakigusangisha aho uri bitagusabye gukora urugendo, aha niho urubuga <strong>Muhahe.com</strong> ruje nk&rsquo;igisubizo kuko bagufitiye byinshi wakenera mubuzima bwa buri munsi bitandukanye kandi muburyo bwo kworohereza abanyarwanda kubera iki kibazo cya Coronavirus, bagabanyije ibiciro (Discount) kugira buriwese abe yabasha kubona icyo akeneye ku mafaranga make kandi bakakigusangisha aho waba uherereye mu mugi wa Kigali ndetse n&rsquo;ahandi.</span></p>\r\n\r\n<p><strong><span style=\"font-size:13.0pt\">Ku rubuga rwacu Muhahe.com wasangaho ibyiciro bitandukanye by&rsquo;ibicuruzwa bitewe n&rsquo;icyo wifuza</span></strong></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<div style=\"border-bottom:double windowtext 2.25pt; padding:0cm 0cm 31.0pt 0cm\">\r\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><strong><span style=\"font-size:13.0pt\">Aha twafata urugero ku bicuruzwa bitandukanye kandi biri kugiciro kiri hasi cyane utasanga ahandi:</span></strong></span></span></p>\r\n\r\n<p><span style=\"font-size:18px\"><span style=\"font-family:Times New Roman,Times,serif\"><strong>1. Udupfuka munwa (Face Masks)</strong></span></span></p>\r\n\r\n<figure class=\"easyimage easyimage-full\"><img alt=\"\" src=\"blob:https://muhahe.com/d041928e-82a7-4dba-81ec-d5044a5b2b98\" width=\"893\" />\r\n<figcaption></figcaption>\r\n</figure>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"font-size:18px\"><span style=\"font-family:Times New Roman,Times,serif\"><strong>2.&nbsp; &nbsp;Intebe</strong></span></span></p>\r\n\r\n<figure class=\"easyimage easyimage-full\"><img alt=\"\" src=\"blob:https://muhahe.com/90eb1b61-c0d6-431b-8ca4-41442b76197d\" width=\"1177\" />\r\n<figcaption></figcaption>\r\n</figure>\r\n\r\n<p><span style=\"font-size:18px\"><span style=\"font-family:Times New Roman,Times,serif\"><strong>3.Imibavu</strong></span></span></p>\r\n\r\n<figure class=\"easyimage easyimage-full\"><img alt=\"\" src=\"blob:https://muhahe.com/9d147024-f635-444b-a07a-6ce1ad8eadf0\" width=\"1129\" />\r\n<figcaption></figcaption>\r\n</figure>\r\n\r\n<figure class=\"easyimage easyimage-full\"><img alt=\"\" src=\"blob:https://muhahe.com/a4a6a6e4-c8ea-4598-9997-0d83a2f096fa\" width=\"1129\" />\r\n<figcaption></figcaption>\r\n</figure>\r\n\r\n<p>👇👇</p>\r\n\r\n<p><span style=\"font-size:24px\"><a href=\"https://muhahe.com/blog/30\"><span style=\"font-family:Times New Roman,Times,serif\">Kanda hano ubone uko wagurira ikintu cyose kuri Muhahe.com muburyo burambuye</span></a></span></p>\r\n</div>', '1593091044mu.JPG', 'muhahe.com', 838, 1, 'buy and sell,sell,buy,ihaha,kugura,store,muhahe,iduka,ibiciro,amafaranga,igurisha', '<p>Menya urubuga waguriraho ndetse ukanacururizaho kuri murandasi ruriguca ibintu.</p>', NULL, '2020-06-25 11:17:24'),
(67, 11, 'Mubyeyi Menya byinshi k\'umenyo y’abana bato nuko wakwita ku isuku yayo .', '<p><span style=\"font-family:Times New Roman,Times,serif\"><em><strong><span style=\"font-size:22px\">Bamwe mu babyeyi usanga bahura n&rsquo;ikibazo cyo kurwaza abana indwara z&rsquo;amenyo n&rsquo;izo mu kanwa bitewe no kutamenya ikigero gikwiriye umwana atangiriraho gukorerwa isuku y&rsquo;amenyo aho bamwe iyo ubabajije niba bibuka gukorera abana babo bato isuku y&#39;amenyo badatinya kukubwirako bitari ngombwa kuko ngo ayo menyo atari ngombwa kuyakorera isuku ko nubundi aba azakuka.</span></strong></em></span></p>\r\n\r\n<p><span style=\"font-size:20px\"><span style=\"font-family:Times New Roman,Times,serif\">Ni mu gihe inyigo yakozwe na SOS mu mwaka wa 2015 ku bana 2063 bo mu turere twa Gasabo, Nyamagabe na Gicumbi igaragaza ko 44% barwaye amenyo n&rsquo;ishinya, nk&rsquo;uko byatangajwe na minis</span></span></p>\r\n\r\n<p><span style=\"font-size:20px\"><span style=\"font-family:Times New Roman,Times,serif\">Umuntu yakwibaza niba uku kurwara indwara z&rsquo;amenyo ku rugero ruri hejuru bidafitanye isano n&rsquo;isuku nke y&rsquo;amenyo kuva umwana atangira kumera amenyo ya mbere.</span></span></p>\r\n\r\n<p><span style=\"font-size:20px\"><span style=\"font-family:Times New Roman,Times,serif\">Iyi nkuru irabafasha gusobanukirwa n&rsquo;uburyo amenyo akurikirana mu kumera, isuku yayo ndetse n&rsquo;ibikenerwa kugira ngo ikorwe neza.</span></span></p>\r\n\r\n<p><span style=\"font-size:20px\"><strong><span style=\"font-family:Times New Roman,Times,serif\">Inkuru dukesha ikinyamakuru babycenter.fr isobanura uko umwana agenda amera amenyo n&#39;ikigero aba agezemo:</span></strong></span></p>\r\n\r\n<p><span style=\"font-size:12pt\"><span style=\"font-size:15.0pt\"><span style=\"font-size:36px\"><strong>. </strong></span> ivuga ko umwana atangira kumera amenyo ya mbere ku mezi hagati ya 5-10, hakabanza rimwe ryo hagati ku&nbsp; ruhande rw&rsquo;ibumoso ku rwasaya rwo hasi.</span></span></p>\r\n\r\n<p><span style=\"font-size:12pt\"><span style=\"font-size:15.0pt\"><span style=\"font-size:36px\"><strong>. </strong></span>Hagati y&rsquo;amezi 6 na 12 hazamuka ay&rsquo;imbere ku rwasaya rwo hejuru, aya asa n&rsquo;azamukira rimwe ari 2.&nbsp; &nbsp; &nbsp; &nbsp;Hagati y&rsquo;amezi 12 na 19 hagenda hazamuka andi menyo n&rsquo;ibijigo bya mbere ku mpande zombi.</span></span></p>\r\n\r\n<p><span style=\"font-size:12pt\"><span style=\"font-size:15.0pt\"><span style=\"font-size:36px\"><strong>. </strong></span> Naho <strong>amabwene </strong>yo kurwasaya rwo hejuru n&rsquo;urwo hasi azamuka hagati y&rsquo;amezi 16 na 22. Hagati y&rsquo;amezi 20 na 31 hamera ibijigo by&rsquo;inyuma ku rwasaya rwo hasi, naho ibijigo by&rsquo;inyuma ku rwasaya rwo hejuru bikamera hagati y&rsquo;amezi 25 na 33 ari na yo aherukira ayandi.</span></span></p>\r\n\r\n<p><span style=\"font-size:12pt\"><span style=\"font-size:15.0pt\"><span style=\"font-size:36px\"><strong>. </strong></span>Ku myaka 3 abana benshi baba bamaze kugira amenyo yuzuye 20. Ni ukuvuga 10 hasi n&rsquo;10 hejuru.</span></span></p>\r\n\r\n<figure class=\"easyimage easyimage-full\"><img alt=\"\" src=\"blob:https://muhahe.com/9b677b6b-1411-453d-8462-416c2675a55c\" width=\"600\" />\r\n<figcaption></figcaption>\r\n</figure>\r\n\r\n<p><span style=\"font-size:20px\"><span style=\"font-family:Times New Roman,Times,serif\">Hari ubwo usanga umwana arinda agira aya menyo uko ari 20 atarakorerwa isuku! Ese ni uko bidakwiye?, ese ni ukutabimenya? Ese ni uko nta bikoresho byagenewe isuku y&rsquo;amenyo ku bana bato?</span></span></p>\r\n\r\n<p><span style=\"font-size:20px\"><span style=\"font-family:Times New Roman,Times,serif\">Ikinyamakuru parent.fr kivuga ko umwana akorerwa isuku y&rsquo;amenyo kuva akimera iryinyo rya mbere, ku mezi 6, bigakorwa inshuro 2 ku munsi hifashishijwe agatambaro gafite isuku cyangwa akitwa compresse (kompurese) n&rsquo;amazi asukuye.</span></span></p>\r\n\r\n<p><span style=\"font-size:20px\"><span style=\"font-family:Times New Roman,Times,serif\">Ikinyamakuru Topsante.com kivuga ko isuku yo mu kanwa n&rsquo;amenyo ku mwana wo munsi y&rsquo;imyaka 2 ikorwa nta muti w&rsquo;amenyo, kuva ku myaka 2 kugera kuri 3 hagakenerwa umuti w&rsquo;amenyo urimo fluor nkeya, guhera kumyaka 3-6 nabwo hagakenerwa umuti urimo fluor iri ku kigero giciriritse, naho kuva ku myaka 6 kuzamura umwana akoresha umuti w&rsquo;amenyo urimo fluor ihagije kimwe n&rsquo;abantu bakuru.</span></span></p>\r\n\r\n<figure class=\"easyimage easyimage-full\"><img alt=\"\" src=\"blob:https://muhahe.com/67694504-eed2-4bfc-9c91-55ddb5bf413f\" width=\"600\" />\r\n<figcaption></figcaption>\r\n</figure>\r\n\r\n<p><span style=\"font-size:20px\"><span style=\"font-family:Times New Roman,Times,serif\"><strong>Isuku y&rsquo;amenyo y&rsquo;abana na yo ni ngombwa kimwe nk&rsquo;abantu bakuru</strong></span></span></p>\r\n\r\n<p><span style=\"font-size:20px\"><span style=\"font-family:Times New Roman,Times,serif\">Umwana kandi yogerezwa amenyo kugera ku myaka 4, guhera aho kuzamura atozwa kubyikorera ariko umuntu mukuru akamuba hafi.</span></span></p>\r\n\r\n<p><span style=\"font-size:20px\"><span style=\"font-family:Times New Roman,Times,serif\">Ku bijyanye n&rsquo;uburoso bwoza amenyo, hari ubwagenewe abana bari munsi y&rsquo;imyaka 10, bugomba kuba ari buto ku buryo bugenda neza mu kanwa butamubabaza, bunafite ubwoya bwegeranye cyane kandi bworohereye.</span></span></p>\r\n\r\n<p><span style=\"font-size:20px\"><span style=\"font-family:Times New Roman,Times,serif\">Guhera ku myaka 10 kuzamura umwana aba ashobora gukoresha ubw&rsquo;abantu bakuru ariko na none butari bunini.</span></span></p>\r\n\r\n<p><span style=\"font-size:20px\"><span style=\"font-family:Times New Roman,Times,serif\">Kutagirira umwana isuku yo mu kanwa n&rsquo;amenyo bimugiraho ingaruka.</span></span></p>\r\n\r\n<p><span style=\"font-size:20px\"><span style=\"font-family:Times New Roman,Times,serif\">Kimwe n&rsquo;abantu bakuru, isuku nke yo mu kanwa n&rsquo;amenyo ku mwana imutera indwara zirimo guhindura ibara kw&rsquo;amenyo cyangwa se gushirira, ndetse no gucukuka.</span></span></p>\r\n\r\n<p><span style=\"font-size:20px\"><span style=\"font-family:Times New Roman,Times,serif\">Iyo amenyo y&rsquo;umwana adafite ubuzima bwiza bigira ingaruka na none mu gutozwa kuvuga.</span></span></p>', '1593179792teeths.jpg', 'kigalitoday', 884, 1, 'ubuzima,muhahe,ihaha,online shopping,iduka,guhaha,shopping,online shopping rwanda,online store,products,ecommerce,amakuru,amakuru agezweho,menya byinshi,sobanukirwa', '<p>Mubyeyi Menya byinshi k&#39;umenyo y&rsquo;abana bato nuko wakwita ku isuku yayo .</p>', NULL, '2020-06-26 11:56:32'),
(69, 11, 'Minicom Yashyize ahagaragara ibiciro by\'ibiribwa bigomba kugenderwaho ku masoko no kuri za ’Boutique’.', '<p><span style=\"font-size:20px\"><span style=\"font-family:Times New Roman,Times,serif\"><strong>Kuri uyu wa kane&nbsp;Minisiteri y&rsquo;ubucuruzi n&rsquo;inganda (Minicom), yashyizeho ibiciro ibiribwa bigomba kugurishwaho ku masoko no kuri za &rsquo;Boutique&rsquo; zitandukanye, ikomeza inibutsa abacuruzi bose kwirinda kuzamura ibiciro by&#39;ibicuruzwa byaba ibikorerwa imbere mu gihugu cyangwa ibitumizwa mu mahanga bitwaje ibihe turimo bya COVID-19.</strong></span></span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:18px\">Minicom yakomeje ivuga ko ibi bitangajwe hashingiwe kuri raporo y&rsquo;igenzura ryakozwe ku masoko atandukanye yo mu Mujyi wa Kigali na zimwe mu ntara, aho byagaragaye ko hari bimwe mu bicuruzwa byazamuriwe ibiciro bamwe mu bacuruzi bitwaje ko igihugu kiri mu bihe bidasanzwe bya Coronavirus,yakomeje akangurira abacuruzi kumanika ibiciro aho bigaragarira abaguzi.</span></span></p>\r\n\r\n<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:18px\">Minisiteri y&rsquo;ubucuruzi n&rsquo;inganda kandi yasabye abaguzi kujya batanga amakuru ku izamuka rikabije ry&rsquo;ibiciro, kugira ngo hafatwe ingamba zihuse aho bibaye ngombwa.</span></span></p>\r\n\r\n<figure class=\"easyimage easyimage-full\"><img alt=\"\" src=\"blob:https://muhahe.com/4790f86b-ca58-49e3-a9bf-d603e268c508\" width=\"1000\" />\r\n<figcaption></figcaption>\r\n</figure>\r\n\r\n<figure class=\"easyimage easyimage-full\"><img alt=\"\" src=\"blob:https://muhahe.com/bc31ff3e-b11c-400a-8043-1c9b4dffd4c0\" width=\"950\" />\r\n<figcaption></figcaption>\r\n</figure>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<figure class=\"easyimage easyimage-full\"><img alt=\"\" src=\"blob:https://muhahe.com/5bf86813-6c85-4de2-bce3-ce6e7d2d0643\" width=\"941\" />\r\n<figcaption></figcaption>\r\n</figure>\r\n\r\n<p>&nbsp;</p>', '1593182918eeee.JPG', 'Igihe', 1498, 1, 'online shopping,muhahe,ihaha,iduka,ibiciro,store in rwanda', '<p>Minicom Yashyize ahagaragara ibiciro by&#39;ibiribwa bigomba kugenderwaho ku masoko no kuri za &rsquo;Boutique&rsquo;.</p>', NULL, '2020-06-26 12:48:38'),
(70, 11, 'Menya Ibintu 5 ugomba kwirinda gukora mugitondo ugikanguka.', '<p><span style=\"font-size:20px\"><span style=\"font-family:Times New Roman,Times,serif\"><strong>Igitondo utangiye neza niryo pfundo ryo kugira umunsi mwiza ndetse w&rsquo;ingirakamaro k&rsquo;ubuzima bwawe. Tugiye kubabwira ibintu ukwiye kwirinda gukora ako kanya ugikanguka.</strong></span></span></p>\r\n\r\n<p><span style=\"font-size:18px\"><span style=\"font-family:Times New Roman,Times,serif\"><strong>1. Kwanga gufata Breakfast</strong></span></span></p>\r\n\r\n<p><span style=\"font-size:18px\"><span style=\"font-family:Times New Roman,Times,serif\">Abantu benshi bakunze kuryamira, nyuma bakabyuka vuba vuba batinze, nuko bagatekera ibintu byose bahita bajya kukazi cyangwa mumirimo itandukanye bigatuma badafata ibyo kurya bya mugitondo, bakaza kurya bwakeye ngo mugitondo bumvaga badashonje. Ese kuki batatakaza igihe mugitondo barya? Ibi ni ukwibeshya cyane, mumasaha 2 ya mugitondo ukimara gukanguka, ni ngombwa gufata ibyo kurya kandi bifite ingufu cyane. Si ngombwa ko wumva ushonje kugira ufate Breakfast ihagije mu gitondo. Impamvu uba ugomba kurya nuko umubiri uba wakoresheje &frac12; cya Calories. Calories ni ingufu dukura mubyo tuba twariye. Mugihe utariye ngo ubone ingufu zihagije, umubiri wawe ntushobora kubona uburyo bwiza bwo gukoresha ibice by&rsquo;imbere mumubiri wawe ndetse no gutuma ubushyuhe mumubiri wawe buguma kukigero kiringaniye. Ibi bikaba cyane mukugira imirimo uri buze gukora kumunsi uze kuyikorana ibakwe ndetse n&rsquo;ingufu zihagije.</span></span></p>\r\n\r\n<p><span style=\"font-size:18px\"><span style=\"font-family:Times New Roman,Times,serif\"><strong>2. Kuguma muburiri uri kuri SmartPhone</strong></span></span></p>\r\n\r\n<p><span style=\"font-size:18px\"><span style=\"font-family:Times New Roman,Times,serif\">Hafi abantu bose ntibajya bashaka gushyira kure SmartPhones zabo, buri wese aba yumva yayiyegereza buri gihe. Usanga twirirwana nazo umunsi wowe, ndetse tukazishyira no mumashuka nijoro. Ni byiza ko igihe igiye kuryama Telefone uyishyira muri Airplane mode. Ibi bizatuma itagukangura kubera Notifications zitandukanye. Mu gitondo tugikanguka ako kanya, dufungura amaso icyambere dukora ari ukureba muri Telefone tureba Message batwoherereje cyane kuri Social Networks harimo nko kuri Whatsapp, facebook, instagram ndetse na Emails. Gusa iki ni igitekerezo kibi. Ni byiza kubyuka wumva utuje ndetse utekanye. Nibyiza ko mugihe ukangutse utagomba gukora kuri Telefone yawe mbere y&rsquo;iminota 30. Ibi bizatuma usinzira neza nijoro kandi bigufashe gutangira imirimo y&rsquo;umunsi neza kandi n&rsquo;ingufu nyinshi.</span></span></p>\r\n\r\n<p><span style=\"font-size:18px\"><span style=\"font-family:Times New Roman,Times,serif\"><strong>3. Kwanga kunywa amazi mugitondo</strong></span></span></p>\r\n\r\n<p><span style=\"font-size:18px\"><span style=\"font-family:Times New Roman,Times,serif\">Abantu benshi barabizi ko bisabwa ko banywa ikirahuri kimwe cy&rsquo;amazi meza kandi asukuye buri gitondo. Gusa n&rsquo;ababikora babikora bigoranye. Ikirahuri kimwe cyamazi unyoye munda ntakintu kirajyamo, ntikiringaniza gusa amazi mumubiri ndetse kinatuma amazi atembere neza, ahubwo kinatuma imyanda iri mumpyiko ibasha gusoka neza kuburyo buboneye.</span></span></p>\r\n\r\n<p><span style=\"font-size:18px\"><span style=\"font-family:Times New Roman,Times,serif\"><strong>4. Kunywa kawa mugitondo&nbsp;</strong></span></span></p>\r\n\r\n<p><span style=\"font-size:18px\"><span style=\"font-family:Times New Roman,Times,serif\">Abantu benshi banywa ikawa nk&rsquo;uburyo bwo kongera imbaraga mumubiri. Mu gitondo, umubiri uba ufite stress kandi kawa iba yifitemo Cortisol yongerera umbiri stress. Umuco wo kunywa kawa mu gitondo, uzatuma uba umunebwe ndetse umubiri wiyumvemo ubwoba. Iki kinyobwa giteza ibibazo iyo ugifashe mugihe mugifu ntakintu kirajyamo. Ubwo rero, mumasaha 3 ukimara kubyuka byaba byiza uretse kunywa ikawa.</span></span></p>\r\n\r\n<p><span style=\"font-size:18px\"><span style=\"font-family:Times New Roman,Times,serif\"><strong>5. Gusasa ako kanya ukimara Kubyuka</strong></span></span></p>\r\n\r\n<p><span style=\"font-size:18px\"><span style=\"font-family:Times New Roman,Times,serif\">Tutitaye ko kuva tukiri bato batwigishije ko uba ugomba gusasa uburiri ako kanya ukimara kubyuka, ntabwo mugomba kubikora. Abahanga mubumenyi bemeje ko haba hari imyanda mito mito igera kuri &frac12; cya miliyoni mu buriri bwacu. Iyo ushashe uburiri ukibyuka, ntabwo bituma umwuka n&rsquo;ubukonje bidakenewe biva mumashuka. Ibi rero biteza GreenHouse effects, ariko gukora imyuka ihumanya muburiri. Ubwo rero kugira wirinde iyi myanda ikorwa igihe uhise usasa, ugomba kureka ibyo warayeho bitatanije nuko ugakingura idirishya nko mugihe cy&rsquo;iminota 30 umwaka mwiza wo hanze ukinjira munzu. Huuuu Ubu noneho umenye uburyo bwiza n&rsquo;impamvu usanga uburiri bw&rsquo;aba celebataires buba budashashe. Nuko baba bakurikiye bakamenya ibikwiye. Nibwo ushobora kuryama ahantu heza kandi hakurinda indwara nyinshi zuruhu.</span></span></p>', '1593297653young-man-waking-up-bed-stretching-his-arms_13339-265231.jpg', 'thehealthy.com', 993, 1, 'ubuzima,online store,online shopping,online shopping rwanda,ihaha,muhahe,iduka,kugura,kugurisha,free,delivery,amakuru agezweho', '<p>Menya Ibintu 5 ugomba kwirinda gukora mugitondo ugikanguka.</p>', NULL, '2020-06-27 20:40:53'),
(71, 11, 'Urutonde rw’ibyihebe 10 byambere byabayeho mumateka y’isi', '<p><strong><span style=\"font-size:20px\"><span style=\"font-family:Times New Roman,Times,serif\">Nyuma y&rsquo;urupfu rwa Osama Bin Laden, waguye mugitero yagabweho n&rsquo;ingabo z&rsquo;Abanyamerika byatumye hibazwango: ninde kihebe kurusha abandi mubyihebe byose byabayeho mumateka y&rsquo;isi?</span></span></strong></p>\r\n\r\n<p><strong><span style=\"font-size:20px\"><span style=\"font-family:Times New Roman,Times,serif\">Muhahe.com yagukoreye urutonde rw&rsquo;ibyihebe 10 rukurikira byabayeho mu mateka y&#39;isi.</span></span></strong></p>\r\n\r\n<h2><span style=\"font-size:20px\"><strong><span style=\"font-family:Times New Roman,Times,serif\">10.&nbsp;<a href=\"https://en.wikipedia.org/wiki/Suharto\" rel=\"noopener\" target=\"_blank\">Suharto</a></span></strong></span></h2>\r\n\r\n<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:18px\">Yavukiye ahitwa Kemusu Argamula muri Indeneziya mu 1921 apfira ahitwa Jakarta muri Indenoziya mu 1998. Uyu nyakwigendera yabaye Umuyobozi mukuru wa Indoneziya kuva 1967 kugeza 1998. Uyu mugihe yayoboraga kino gihugu yakoze ubwicanyi byatwaye ubuzima bw&rsquo;inzirakarengane zisaga 800,000.</span></span></p>\r\n\r\n<figure class=\"easyimage easyimage-full\"><img alt=\"\" src=\"blob:https://muhahe.com/ada42930-6a15-4ce0-b353-0518dca407bd\" width=\"3136\" />\r\n<figcaption></figcaption>\r\n</figure>\r\n\r\n<p><span style=\"font-size:20px\"><span style=\"font-family:Times New Roman,Times,serif\"><strong>9</strong>.&nbsp;<a href=\"https://en.wikipedia.org/wiki/Benito_Mussolini\" rel=\"noopener\" target=\"_blank\"><strong>Benito Mussolini</strong></a></span></span></p>\r\n\r\n<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:18px\">Yavutse ku 29 Nyakanga, 1883 apfa kuwa 28 Mata, 1945 muntambara ya kabiri y&rsquo;isi. Uyu yari umunyagitugu w&rsquo;umutariyani akaba. Yaranzwe n&rsquo;amahame ndetse n&rsquo;imyanzuro bikakaye aribyo byabaye intandaro y&rsquo;impfu z&rsquo;abasaga 300 000 mugihe cy&rsquo;ubutegetsi bwe.</span></span></p>\r\n\r\n<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:18px\"><img alt=\"\" height=\"641\" sizes=\"(max-width: 708px) 100vw, 708px\" src=\"https://i0.wp.com/www.menyabyinshi.com/wp-content/uploads/2018/03/9-2-300x272.jpg?resize=708%2C641&amp;ssl=1\" srcset=\"https://i1.wp.com/www.menyabyinshi.com/wp-content/uploads/2018/03/9-2.jpg?resize=300%2C272&amp;ssl=1 300w, https://i1.wp.com/www.menyabyinshi.com/wp-content/uploads/2018/03/9-2.jpg?resize=768%2C695&amp;ssl=1 768w, https://i1.wp.com/www.menyabyinshi.com/wp-content/uploads/2018/03/9-2.jpg?w=1024&amp;ssl=1 1024w\" width=\"708\" /></span></span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h2><span style=\"font-size:20px\"><span style=\"font-family:Times New Roman,Times,serif\"><strong>8.&nbsp;<a href=\"https://en.wikipedia.org/wiki/Leopold_II_of_Belgium\" rel=\"noopener\" target=\"_blank\">Umwami Leopold II</a></strong></span></span></h2>\r\n\r\n<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:18px\">King Leopold II yavukiye mumurwa mukuru w&rsquo;Ububirigi, Brussels, mu mwaka wa 1835 apfira ahitwa Laeken mu mwaka wa 1909. Uyu yabaye umwami w&rsquo;ububirigi kuva 1865 kugeza 1909. Uyu yakoze ubwicanyi bwatwaye ubuzima bw&rsquo;inzirakarengane z&rsquo;abasangwabutaka babanyekongo basaga miliyoni 8 000 000.</span></span></p>\r\n\r\n<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:18px\"><img alt=\"\" height=\"810\" sizes=\"(max-width: 708px) 100vw, 708px\" src=\"https://i2.wp.com/www.menyabyinshi.com/wp-content/uploads/2018/03/8-1-262x300.jpg?resize=708%2C810&amp;ssl=1\" srcset=\"https://i1.wp.com/www.menyabyinshi.com/wp-content/uploads/2018/03/8-1.jpg?resize=262%2C300&amp;ssl=1 262w, https://i1.wp.com/www.menyabyinshi.com/wp-content/uploads/2018/03/8-1.jpg?resize=768%2C879&amp;ssl=1 768w, https://i1.wp.com/www.menyabyinshi.com/wp-content/uploads/2018/03/8-1.jpg?w=895&amp;ssl=1 895w\" width=\"708\" /></span></span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h2><span style=\"font-size:20px\"><span style=\"font-family:Times New Roman,Times,serif\"><strong>7.&nbsp;<a href=\"https://en.wikipedia.org/wiki/Genghis_Khan\" rel=\"noopener\" target=\"_blank\">Genghis Khan</a></strong></span></span></h2>\r\n\r\n<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:18px\">Yavutse 1162 apfa 1227. Uyu nyakwigendera yashinze ubwami bunini cyane bwari bugizwe n&rsquo;ibice by&rsquo;ubushinwa, Aziya&nbsp; yo hagati, uburasirazuba bwohagati ndetse n&rsquo;uburayi. Ubwo bwami bugereranwa mungano nikitwa Afurika y&rsquo;ubu. Uyumwami mugihe yayoboraga yishe ubuzima bw&rsquo;inzirakarengane zisaga miliyoni ebyiri n&rsquo;igice (2 500 000).</span></span></p>\r\n\r\n<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:18px\"><img alt=\"\" height=\"940\" sizes=\"(max-width: 708px) 100vw, 708px\" src=\"https://i1.wp.com/www.menyabyinshi.com/wp-content/uploads/2018/03/7-2-226x300.jpg?resize=708%2C940&amp;ssl=1\" srcset=\"https://i1.wp.com/www.menyabyinshi.com/wp-content/uploads/2018/03/7-2.jpg?resize=226%2C300&amp;ssl=1 226w, https://i1.wp.com/www.menyabyinshi.com/wp-content/uploads/2018/03/7-2.jpg?resize=768%2C1019&amp;ssl=1 768w, https://i1.wp.com/www.menyabyinshi.com/wp-content/uploads/2018/03/7-2.jpg?w=772&amp;ssl=1 772w\" width=\"708\" /></span></span></p>\r\n\r\n<h2><span style=\"font-size:20px\"><span style=\"font-family:Times New Roman,Times,serif\"><strong>6.&nbsp;<a href=\"https://en.wikipedia.org/wiki/Idi_Amin\" rel=\"noopener\" target=\"_blank\">Idi Amin Dada</a></strong></span></span></h2>\r\n\r\n<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:18px\">Yavukiye ahitwa Koboko muri Uganda mu 1924 apfira ahitwa Jiddah muri Saudi Arabia tariki y 16 Kanama muri 2003. Uyu yabaye umuyobozi mukuru w&rsquo;Ubugande mugihe cy&rsquo;imyaka 8&nbsp; kuva 1971 kugeza 1979, akaba yararanzwe no kutubahiriza uburenganzira bw&rsquo;ikiremwamuntu, igitugu, ubwicanyi, ruswa, ndetse no kutabungabunga ubukungu bw&rsquo;igihugu neza. Uyu kandi yagize uruhari murupfu rw&rsquo; inzirakarengane zisaga 300 000.</span></span></p>\r\n\r\n<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:18px\"><img alt=\"\" height=\"413\" sizes=\"(max-width: 708px) 100vw, 708px\" src=\"https://i2.wp.com/www.menyabyinshi.com/wp-content/uploads/2018/03/6-1-1024x598.jpg?resize=708%2C413&amp;ssl=1\" srcset=\"https://i2.wp.com/www.menyabyinshi.com/wp-content/uploads/2018/03/6-1.jpg?w=1024&amp;ssl=1 1024w, https://i2.wp.com/www.menyabyinshi.com/wp-content/uploads/2018/03/6-1.jpg?resize=300%2C175&amp;ssl=1 300w, https://i2.wp.com/www.menyabyinshi.com/wp-content/uploads/2018/03/6-1.jpg?resize=768%2C449&amp;ssl=1 768w, https://i2.wp.com/www.menyabyinshi.com/wp-content/uploads/2018/03/6-1.jpg?resize=752%2C440&amp;ssl=1 752w\" width=\"708\" /></span></span></p>\r\n\r\n<h4><span style=\"font-size:20px\"><span style=\"font-family:Times New Roman,Times,serif\"><strong>5.&nbsp;<a href=\"https://en.wikipedia.org/wiki/Saddam_Hussein\" rel=\"noopener\" target=\"_blank\">Saddam Hussein</a></strong></span></span></h4>\r\n\r\n<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:18px\">Saddam Hussein yavukiye ahitwa Tikrist muri Iraq kuwa 28 Mata, 1937. Yabaye umuyobozi mukuru wa Iraq kuva 1979 kugeza 2003 ubwo yanyongwaga n&rsquo;Abanyamerika kungoma ya George W Bush. Uyu yishe ibihumbi n&rsquo;ibihumbi by&rsquo;abaturage be akoresheje ubumara bw&rsquo;umwuka.</span></span></p>\r\n\r\n<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:18px\"><img alt=\"\" height=\"496\" sizes=\"(max-width: 708px) 100vw, 708px\" src=\"https://i1.wp.com/www.menyabyinshi.com/wp-content/uploads/2018/03/5-3-300x210.jpg?resize=708%2C496&amp;ssl=1\" srcset=\"https://i2.wp.com/www.menyabyinshi.com/wp-content/uploads/2018/03/5-3.jpg?resize=300%2C210&amp;ssl=1 300w, https://i2.wp.com/www.menyabyinshi.com/wp-content/uploads/2018/03/5-3.jpg?resize=768%2C537&amp;ssl=1 768w, https://i2.wp.com/www.menyabyinshi.com/wp-content/uploads/2018/03/5-3.jpg?w=1024&amp;ssl=1 1024w, https://i2.wp.com/www.menyabyinshi.com/wp-content/uploads/2018/03/5-3.jpg?resize=120%2C85&amp;ssl=1 120w\" width=\"708\" /></span></span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h2><span style=\"font-size:20px\"><span style=\"font-family:Times New Roman,Times,serif\"><strong>4.&nbsp;<a href=\"https://en.wikipedia.org/wiki/Joseph_Stalin\" rel=\"noopener\" target=\"_blank\">Joseph Stalin</a></strong></span></span></h2>\r\n\r\n<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:18px\">Yavukiye ahitwa Gori muri Georgia kuwa 18 Ukuboza, 1879. Uyu yabaye umwanditsi mukuru w&rsquo;umutwe w&rsquo;abasoviyeti. Uyu yishe abaturage benshi abandi abakura mubyabo abafungirana mu nkambi bamwe muribo bapfirayo kubera ubuzima bubi cyane bari babayemo.</span></span></p>\r\n\r\n<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:18px\"><img alt=\"\" height=\"926\" sizes=\"(max-width: 708px) 100vw, 708px\" src=\"https://i2.wp.com/www.menyabyinshi.com/wp-content/uploads/2018/03/4-3-229x300.jpg?resize=708%2C926&amp;ssl=1\" srcset=\"https://i0.wp.com/www.menyabyinshi.com/wp-content/uploads/2018/03/4-3.jpg?resize=229%2C300&amp;ssl=1 229w, https://i0.wp.com/www.menyabyinshi.com/wp-content/uploads/2018/03/4-3.jpg?resize=768%2C1005&amp;ssl=1 768w, https://i0.wp.com/www.menyabyinshi.com/wp-content/uploads/2018/03/4-3.jpg?w=782&amp;ssl=1 782w\" width=\"708\" /></span></span></p>\r\n\r\n<h2><span style=\"font-size:20px\"><span style=\"font-family:Times New Roman,Times,serif\"><strong>3.&nbsp;<a href=\"https://en.wikipedia.org/wiki/Osama_bin_Laden\" rel=\"noopener\" target=\"_blank\">Osama Bin Laden</a></strong></span></span></h2>\r\n\r\n<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:18px\">Osama Bin Laden yavukiye ahitwa Saudi Arabia mu 1957 apfira ahitwa Abbottabad mura Pakistan tariki 2, Gicurasi 2011 mugitero yagabweho n&rsquo;ingabo z&rsquo;Abanyamerika. Uyu yashinjwaga gushinga umutwe w&rsquo;iterabwoba wa Al-Qaeda ndetse no kugaba igitero ku igorofa ryari riri mumugi wa NewYork akarisenya. Uyu mubikorwa byose by&rsquo;ubwiyahuzi yakoze byatwaye ubuzima bw&rsquo;abasaga 4 000.</span></span></p>\r\n\r\n<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:18px\"><img alt=\"\" height=\"513\" sizes=\"(max-width: 708px) 100vw, 708px\" src=\"https://i2.wp.com/www.menyabyinshi.com/wp-content/uploads/2018/03/3-3-300x217.jpg?resize=708%2C513&amp;ssl=1\" srcset=\"https://i0.wp.com/www.menyabyinshi.com/wp-content/uploads/2018/03/3-3.jpg?resize=300%2C217&amp;ssl=1 300w, https://i0.wp.com/www.menyabyinshi.com/wp-content/uploads/2018/03/3-3.jpg?resize=768%2C556&amp;ssl=1 768w, https://i0.wp.com/www.menyabyinshi.com/wp-content/uploads/2018/03/3-3.jpg?w=1024&amp;ssl=1 1024w\" width=\"708\" /></span></span></p>\r\n\r\n<h2><span style=\"font-size:20px\"><span style=\"font-family:Times New Roman,Times,serif\"><strong>2.&nbsp;<a href=\"https://en.wikipedia.org/wiki/Mao_Zedong\" rel=\"noopener\" target=\"_blank\">Chairman Mao</a></strong></span></span></h2>\r\n\r\n<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:18px\">Uyu yavukiye ahitwa Shaoshan kuwa 26 Ugushingo, 1893 aphira ahitwa Beijing tariki 9 Nzeri 1976. Mao yari umunyamatwara w&rsquo;umushinwa. Uyu kandi ashinjwa kugira uruhari murupfu rw&rsquo;abasaga miliyoni 60.</span></span></p>\r\n\r\n<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:18px\"><img alt=\"\" height=\"465\" sizes=\"(max-width: 708px) 100vw, 708px\" src=\"https://i0.wp.com/www.menyabyinshi.com/wp-content/uploads/2018/03/2-5-300x197.jpg?resize=708%2C465&amp;ssl=1\" srcset=\"https://i1.wp.com/www.menyabyinshi.com/wp-content/uploads/2018/03/2-5.jpg?resize=300%2C197&amp;ssl=1 300w, https://i1.wp.com/www.menyabyinshi.com/wp-content/uploads/2018/03/2-5.jpg?resize=768%2C505&amp;ssl=1 768w, https://i1.wp.com/www.menyabyinshi.com/wp-content/uploads/2018/03/2-5.jpg?w=1024&amp;ssl=1 1024w\" width=\"708\" /></span></span></p>\r\n\r\n<h2><span style=\"font-size:20px\"><span style=\"font-family:Times New Roman,Times,serif\"><strong>1.&nbsp;<a href=\"https://en.wikipedia.org/wiki/Adolf_Hitler\" rel=\"noopener\" target=\"_blank\">Adolf Hitler</a></strong></span></span></h2>\r\n\r\n<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:18px\">Adolf Hitler yavukiye ahitwa&nbsp; Braunau mumugi wa Austria uhana imbibe n&rsquo;Ubudage tariki ya 20 Mata, 1889 apfira ahitwa&nbsp; Berlin tariki ya 30 Mata 1945 muntambara ya 2 y&rsquo;isi. Ubwo &nbsp;Hitireri yari afite imyaka 3 umuryango we wimukiye mubudage. Mu mwaka wa 1933 kugeza 1945 yabaye umuyobozi mukuru w&rsquo;umutwe yari uyoboye witwaga Nazi. Ubuyobozi bw&rsquo;uyu mugabo bwabaye intandaro yintambara 2 y&rsquo;isi. Yakoreye ubwicanyi ndenga kamere abayahudi basaga miriyoni 6. Uyu mugabo muri rusange yagize uruhare murupfu rw&rsquo;abasaga miriyoni 23.</span></span></p>', '1593444941hitler.jpg', 'historybehind', 975, 1, 'online store,kigali shopping,online store rwanda,ihaha,delivery in kigali,ecommerce shop,selling and buying', '<p>Urutonde rw&rsquo;ibyihebe 10 byambere byabayeho mumateka y&rsquo;isi</p>', NULL, '2020-06-29 13:35:41'),
(72, 8, 'Byinshi wamenya ku ifoto itangaje ushyira muri telephone igahita izima', '<p><span style=\"font-size:20px\"><strong><span style=\"background-color:white\"><em>Buri muntu wese utunze telefone igezweho aba agomba kugira ifoto itatse muri iyo telefone ye(wallpaper) kuburyo iyo uyakije uhita uyibona mu kirahuri cy&rsquo;iyo telefone, abenshi usanga bakunda gushyiramo amafoto yabo cyangwa ay&rsquo;abantu bakunda.</em></span></strong></span></p>\r\n\r\n<p><span style=\"font-size:18px\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"background-color:white\">Ikirimo kuvugwa cyane ni iyi foto igaragaza imiterere nyaburanga hamwe n&rsquo;ikiyaga n&rsquo;izuba rirenga inyuma y&rsquo;imisozi&nbsp; ku buryo bikurura ibyiyumviro by&rsquo;umuntu akaba yahitamo kuyikoresha ataka &nbsp;terefone ye(wallpaper) atazuyaje. Ariko iyi foto igaragara inyuma nk&rsquo;isanzwe byatunguye abantu bagiye bayikoresha muri telefone zabo zikoresha uburyo bwa Android kuko telefone zabo zihita zizimya zikongera zikiyatsa bitunguranye nyuma y&rsquo;uko bayishyize muri telefone bataka ikirahuri cyayo (wallpaper).Amwe mu materefone yibasiwe niyi foto ni nka Samsung na Google Pixel.</span></span></span></p>\r\n\r\n<p><span style=\"font-size:18px\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"background-color:white\">Rimwe na rimwe, terefone ihatirwa kongera kwinjizamo porogaramu ya Android binyuze muri serivisi isanzwe y&rsquo;ububiko bwa porogaramu. BBC ikaba iburira abantu kudakoresha iyifoto.</span></span></span></p>\r\n\r\n<p><span style=\"font-size:18px\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"background-color:white\">Samsung yamaze gutangaza ko izashyira ahagaragara igisubizo cyayo ku ya 11 Kamena kugirango ikosore ayo makosa.</span></span></span></p>\r\n\r\n<figure class=\"easyimage easyimage-full\"><img alt=\"\" src=\"blob:https://muhahe.com/c2eb8941-9e07-467e-b3d9-2b6266240e07\" width=\"300\" />\r\n<figcaption></figcaption>\r\n</figure>\r\n\r\n<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:18px\"><span style=\"background-color:white\">BBC yagerageje gushaka ibisobanuro kuri Google, ariko ntiyabona igisubizo ako kanya.</span></span></span></p>\r\n\r\n<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:18px\"><span style=\"background-color:white\">Abakoresha imbuga nkoranyambaga bamenyeshejwe ikibazo.</span></span></span></p>\r\n\r\n<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:18px\"><span style=\"background-color:white\">Umuburo umwe wakwirakwiriye kuri Twitter bagira bati: &rdquo; Niba umuntu ayikoherereje, nyamuneka wirengagize ntuzayifungure &lsquo;.</span></span></span></p>\r\n\r\n<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:18px\"><span style=\"background-color:white\">Ntukoreshe iyi foto mugutaka telefone yawe [Wallpaper}, cyane cyane muri terefone ya Samsung.Kuko Bizatera terefone yawe gutakaza amakuru!</span></span></span></p>\r\n\r\n<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:18px\"><span style=\"background-color:white\">Umunyamakuru w&rsquo;ikoranabuhanga Bogdan Petrovan yavuze ko iyo virusi itagize ingaruka kuri terefone ye ya Huawei P20 Pro, ariko ko yabujije telefone ya Google Pixel 2 gukora.Nyuma yo gukoresha iyi foto nka wallpaper muri telefone yahise yizimya ako kanya.</span></span></span></p>\r\n\r\n<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:18px\"><span style=\"background-color:white\">Ati: &rdquo; Nagerageje kongera kuyatsa bundi bushya ariko igakomeza kwizimya yongera yiyatsa inshuro nyinshi ibyo byatumye ntongera kubona uko nkoresha iyo telephone&rdquo;.</span></span></span></p>\r\n\r\n<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:18px\"><span style=\"background-color:white\">Iyo virus bigaragara ko igira ingaruka kuri terefone zimwe ariko ntabwo terefone zose zikoresha uburyo bw&rsquo;imikorere (system) bwa Google.</span></span></span></p>\r\n\r\n<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:18px\"><span style=\"background-color:white\">Nawe rero uragirwa inama yo kutazigera ukinisha gufungura iyi foto muri telefone yawe niba udashaka ko yangirika.</span></span></span></p>\r\n\r\n<p>&nbsp;</p>', '1593525360image-660x360.jpg', 'hacklife', 1334, 1, 'store in kigali,store in rwanda,online store in kigali,online store in rwanda,e-commerce in kigali,e-commerce in rwanda,e-commerce websites in rwanda,online delivery,online delivery in rwanda,kigali shops,buy and sell in kigali,buying and selling', '<p>Byinshi wamenya ku ifoto itangaje ushyira muri telephone igahita izima</p>', NULL, '2020-06-30 11:56:00'),
(73, 9, 'Menya urubuga ruriguca ibintu muri Kigali mu guhuza byoroshye umucuruzi n’umuguzi ndetse rugafasha abantu kugura no kugurisha ibicuruzwa kuri murandasi.”', '<p><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><strong><em>&nbsp;</em></strong><strong><em><span style=\"font-size:14.0pt\">Uko imyaka igenda yiyongera ni nako iterambere naryo rirushaho kuba ryiza,ibikorwa bitandukanye bigasimbuzwa ikoranabuhanga aho umuntu ashobora kugura icyo ashaka cyose kw&#39;isi bakakimusangisha aho atuye atiriwe asohoka mu nzu.si ibyo gusa kuko ushobora kuba wagaragaza ndetse ukanacuruza ibicuruzwa byawe kuri murandasi aho isi yose iba ibibonera icyarimwe kuburyo ugikeneye wese bimworohera kukibona .</span></em></strong></span></span></p>\r\n\r\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:14.0pt\">Mu myaka mike ishize byari bisa naho bigoranye kwamamaza&nbsp; ibicuruzwa byawe ku bantu benshi kuko byagusabaga kwishyura amafaranga Atari make kuri Radio cyangwa kuri Televiziyo kugira ngo bakwamamarize ibikorwa byawe, kandi ugasanga byumviswe n&rsquo;abantu batari benshi kandi bikaba bigoye kuba wakwongera ukabyumva mugihe wacikanwe. Ntabwo bikiri ibanga ko turi mu kinyejana cya murandasi aho igura n&rsquo;igurisha bisigaye bikorerwa kuri murandasi, ndetse no kwamamaza ibicuruzwa cyangwa ibikorwa ukora bikagera kw&rsquo;isi yose kandi mu buryo burambye aho bitandukanye cyane n&rsquo;uburyo bwari busanzwe bukoreshwa twavuze haruguru .</span></span></span></p>\r\n\r\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:14.0pt\">Urubuga Muhahe.com ruje gufasha byimazeyo umuguzi ndetse n&rsquo;umucuruzi kubahuriza hamwe aho umucuruzi ashobora kugurisha ibicuruzwa bye yifashishije uru rubuga ndetse n&rsquo;umuguzi akaba yabona ibicuruzwa yifuza ndetse buri kimwe aguze bakakimusangisha aho aherereye bitamusabye gukora urugendo.</span></span></s