INSERT INTO `email_templates` (`id`, `email_type`, `email_subject`, `email_body`, `status`) VALUES
(1, 'new_order', 'Your Order Placed Successfully', '<p>Hello {customer_name},<br>Your Order Number is {order_number}<br>Your order has been placed successfully</p>', 1),
(2, 'new_registration', 'Welcome To Royal Commerce', '<p>Hello {customer_name},<br>You have successfully registered to {website_title}, We wish you will have a wonderful experience using our service.</p><p>Thank You<br></p>', 1),
(3, 'vendor_accept', 'Your Vendor Account Activated', '<p>Hello {customer_name},<br>Your Vendor Account Activated Successfully. Please Login to your account and build your own shop.</p><p>Thank You<br></p>', 1),
(4, 'subscription_warning', 'Your subscrption plan will end after five days', '<p>Hello {customer_name},<br>Your subscription plan duration will end after five days. Please renew your plan otherwise all of your products will be deactivated.</p><p>Thank You<br></p>', 1);
INSERT INTO `faqs` (`id`, `title`, `details`, `status`) VALUES
(1, 'IT support services', '<style type=\"text/css\">\r\n		@page { margin: 0.79in }\r\n		p { margin-bottom: 0.1in; line-height: 115% }\r\n		a:link { so-language: zxx }\r\n	</style>\r\n\r\n\r\n<p>\r\n<font color=\"#000000\"><font face=\"Ubuntu\"><font style=\"font-size: 12pt\"><span style=\"background: transparent\"><span style=\"font-variant-numeric: normal; font-variant-east-asian: normal;\">Do\r\nyou have any inquiry about technology issues like Windows\r\ninstallation, maintenance, software problems, antivirus… Muhahe\r\nbrought you a group of professional IT’s to solve those issues. In\r\naddition to that, we provide training on web development, hosting and\r\nhow you can solve all PC issues without spending much money to the\r\ntechnicians.</span></span></font></font></font></p><p style=\"font-style: normal; font-weight: normal\"><font color=\"#000000\"><font face=\"Ubuntu\"><font size=\"3\" style=\"font-size: 12pt\"><span style=\"background: transparent\"><span style=\"font-variant: normal\"><span style=\"letter-spacing: normal\">Firefighting the system consists of 3 parts large store of water tanks, specialized\r\npumping system and large network of pipes ending in either hydrant\r\nand sprinklers. Muhahe brought for you different products for\r\nfighting fire problems such as:</span></span></span></font></font></font></p><p style=\"margin-left: 0.5in; margin-bottom: 0in; border: none; padding: 0in; font-style: normal; font-weight: normal; line-height: 138%\">\r\n<font color=\"#000000\"><font face=\"Ubuntu\"><font size=\"3\" style=\"font-size: 12pt\"><span style=\"background: transparent\">-&nbsp;\r\n&nbsp; &nbsp; &nbsp; &nbsp; Fire extinguishers</span></font></font></font></p><p style=\"margin-left: 0.5in; margin-bottom: 0.11in; border: none; padding: 0in; font-style: normal; font-weight: normal; line-height: 138%\">\r\n<font color=\"#000000\"><font face=\"Ubuntu\"><font size=\"3\" style=\"font-size: 12pt\"><span style=\"background: transparent\">-&nbsp;\r\n&nbsp; &nbsp; &nbsp; &nbsp; Firefighter jacket, trousers ,\r\nhelmet, boots, gas</span></font></font></font></p><p style=\"margin-bottom: 0.11in; font-style: normal; font-weight: normal; line-height: 138%\">\r\n<font color=\"#000000\"><span style=\"background: transparent\">&nbsp;&nbsp;<font face=\"Ubuntu\"><font size=\"3\" style=\"font-size: 12pt\">­\r\n- Hose Boxes</font></font></span></font></p><p style=\"margin-left: 0.5in; margin-bottom: 0.11in; border: none; padding: 0in; font-style: normal; font-weight: normal; line-height: 138%\">\r\n<font color=\"#000000\"><font face=\"Ubuntu\"><font size=\"3\" style=\"font-size: 12pt\"><span style=\"background: transparent\">-&nbsp;\r\n&nbsp; &nbsp; &nbsp; &nbsp; Fire bucket stand</span></font></font></font></p><style type=\"text/css\">\r\n		@page { margin: 0.79in }\r\n		p { margin-bottom: 0.1in; line-height: 115% }\r\n		a:link { so-language: zxx }\r\n	</style>', 1),
(3, 'Professional graphic Design and logo', '<style type=\"text/css\">\r\n		@page { margin: 0.79in }\r\n		p { margin-bottom: 0.1in; line-height: 115% }\r\n		a:link { so-language: zxx }\r\n	</style>\r\n\r\n\r\n<p>\r\n<font color=\"#000000\"><font face=\"Ubuntu\"><font style=\"font-size: 12pt\"><span style=\"background: transparent\"><span style=\"font-variant-numeric: normal; font-variant-east-asian: normal;\">Graphic\r\ndesigners and other advertisers are constantly tasked with using\r\ncreative, fresh ideas to intrigue audiences. As a graphic designer with\r\nprofessionalism muhahe develop flyers, banners, banderols,\r\nbrochures, business cards, posters, post cards, the layout of magazines\r\nand newspapers.</span></span></font></font></font></p>', 1),
(4, 'Website Development', '<style type=\"text/css\">\r\n		@page { margin: 0.79in }\r\n		h2.cjk { font-family: \"Noto Sans CJK SC\" }\r\n		h2.ctl { font-family: \"Lohit Devanagari\" }\r\n		p { margin-bottom: 0.1in; line-height: 115% }\r\n		a:link { so-language: zxx }\r\n	</style>\r\n\r\n\r\n<p style=\"font-variant-numeric: normal; font-variant-east-asian: normal;\">\r\n<font color=\"#000000\"><font face=\"Ubuntu\"><font style=\"font-size: 12pt\"><span style=\"background: transparent\">-\r\n&nbsp; &nbsp; &nbsp; Static sites are non-editable internet\r\nsites, A brochure website is quite often an online extension of your\r\nsales collateral; outlining the who, what &amp; where of your\r\nbusiness. It is how most organizations start out on the web. For\r\nsome, a simple online brochure that rarely changes is enough.\r\nHowever, most small businesses at least require the option to add and\r\nedit their own news articles. In these situations, a simple tool like\r\nPerch is ideal. This allows the maximum of creativity, with the added\r\noption of making some elements of the page editable.</span></font></font></font></p>\r\n<p style=\"font-variant-numeric: normal; font-variant-east-asian: normal;\">\r\n<font color=\"#000000\"><font face=\"Ubuntu\"><font style=\"font-size: 12pt\"><span style=\"background: transparent\">Most\r\nof the website briefs or requests for a proposal that we receive spec\r\na full content management system (CMS). In reality, most\r\norganizations do not actually use the full capabilities of the CMS,\r\nonly ever updating their news and staff pages. So, as mentioned\r\nearlier, be sure that you have the resources available before you\r\nstart down the ‘full CMS’ path.</span></font></font></font></p>\r\n<h2 class=\"western\" style=\"font-variant-numeric: normal; font-variant-east-asian: normal;\">\r\n<font color=\"#000000\"><font face=\"Ubuntu\"><font style=\"font-size: 12pt\"><span style=\"background: transparent\">-&nbsp;\r\n&nbsp; &nbsp; &nbsp; &nbsp; Editable Brochure Sites: Requires a\r\ncontent management system.&nbsp; What is a content management system?\r\nA Content Management System (CMS) is a web-based tool to allow any\r\nauthorized user access to edit the website. The idea behind a CMS is\r\nthat the client who, typically, has no prior experience in web page\r\nprogramming handles day-to-day maintenance. By using modern\r\nprogramming languages and WYSIWYG (pronounced ‘whizzy wig’ –\r\nmeaning ‘What You See Is What You Get’) editors look and work in\r\na similar way to Microsoft Word, but convert the content in HTML (the\r\nlanguage of the web). None of them is perfect, but they certainly\r\nmake it easier &amp; quicker to publish to your website.</span></font></font></font></h2>\r\n<p style=\"font-variant-numeric: normal; font-variant-east-asian: normal;\">\r\n<font color=\"#000000\"><font face=\"Ubuntu\"><font style=\"font-size: 12pt\"><span style=\"background: transparent\">We\r\nfind that people who are proficient in Word can easily work a CMS and\r\nhave the ability to create new content, add content, insert images\r\nand control what is on the website.</span></font></font></font></p>\r\n<p style=\"font-variant-numeric: normal; font-variant-east-asian: normal;\">\r\n<font color=\"#000000\"><font face=\"Ubuntu\"><font style=\"font-size: 12pt\"><span style=\"background: transparent\">Most\r\nCMSs will store the content of the web page in a database table,\r\nmeaning it is searchable and can have various Metadata attached to\r\nit. It also means that you can have various version of the same page\r\n(for example, the live version, older versions and perhaps a new\r\nversion that is not yet complete.) This makes CMS a very powerful\r\ntool for managing the site content.</span></font></font></font></p>\r\n<p style=\"font-variant-numeric: normal; font-variant-east-asian: normal;\">\r\n<font color=\"#000000\"><font face=\"Ubuntu\"><font style=\"font-size: 12pt\"><span style=\"background: transparent\">Fully\r\nfunctioning content management systems come in many different guises,\r\nthankfully, there are now some excellent off-the-shelf options\r\navailable. Some of them are free to use, such as WordPress and some\r\nrequire the purchase of a license, such as Craft (our preferred\r\nchoice).</span></font></font></font></p>\r\n<p style=\"font-variant-numeric: normal; font-variant-east-asian: normal;\">\r\n<font color=\"#000000\"><font face=\"Ubuntu\"><font style=\"font-size: 12pt\"><span style=\"background: transparent\">As\r\na word of advice, if you don’t need particularly bespoke\r\nfunctionality to try and stick to using a popular, reliable CMS. There\r\nis little point building a completely bespoke CMS just to add, edit\r\nand delete pages, news and blog posts. It simply isn’t necessary\r\nanymore. In addition, most of the mainstream CMSs have thousands of\r\nplugins available that will facilitate all manner of things, such as\r\nanimated banner photos, photo galleries, dynamic (editable) contact\r\nforms, etc. Don’t try to re-create the wheel unless you have to.</span></font></font></font></p>\r\n<p style=\"font-variant-numeric: normal; font-variant-east-asian: normal;\">\r\n<font color=\"#000000\">&nbsp;</font></p>\r\n<p style=\"font-variant-numeric: normal; font-variant-east-asian: normal;\">\r\n<font color=\"#000000\"><font face=\"Ubuntu\"><font style=\"font-size: 12pt\"><span style=\"background: transparent\">§&nbsp;\r\nEditable Dynamic Website: It engages the user with login areas. This\r\nsite is self-managed.</span></font></font></font></p>\r\n<p><span style=\"font-variant-numeric: normal; font-variant-east-asian: normal;\"><font color=\"#000000\"><font face=\"Ubuntu\"><font style=\"font-size: 12pt\"><span style=\"background: transparent\">E-commerce\r\nWebsites: E-commerce is a favorite type of website globally due to\r\nthe marketing nature of it. Buyers meet sellers and transactions such\r\nas ordering, payments, and shipping are capable online due to the\r\ncontent management system involved. An e-commerce website contains\r\nthe sales pitch zone, the products zone, and the customer check-in\r\nand out the process, they have a payment gateway, e.g., PayPal. The\r\ne-commerce platform has been developed thousands of times; it has\r\nbeen refined, improved upon and extended. As with content\r\nmanagement systems, there are many excellent e-commerce platforms\r\navailable. Ranging from the cheap and easy to setup hosted options\r\nlike <a href=\"https://shopify.com/\" target=\"_blank\">Shopify</a>\r\nthrough to the more advanced <a href=\"https://magentocommerce.com/\" target=\"_blank\">Magneto</a>.</span></font></font></font></span></p>\r\n<p><span style=\"font-variant-numeric: normal; font-variant-east-asian: normal;\"><font color=\"#000000\"><font face=\"Ubuntu\"><font style=\"font-size: 12pt\"><span style=\"background: transparent\">When\r\ndeciding which approach to take, be clear about your requirements.\r\nHow many product lines, how many variants of each product, do you\r\nneed to integrate it with a fulfillment house? Which payment gateway\r\ndo you want to use? (If you are not sure, compare them here: <a href=\"http://paymentbrain.co.uk/\" target=\"_blank\">Payment\r\nBrain</a>) All of these decisions will influence the approach you\r\nneed to take.</span></font></font></font></span></p>\r\n<p style=\"font-variant-numeric: normal; font-variant-east-asian: normal;\">\r\n<font color=\"#000000\"><font face=\"Ubuntu\"><font style=\"font-size: 12pt\"><span style=\"background: transparent\">E-commerce\r\nwebsites demand a lot more attention than a normal brochure website.\r\nYou simply cannot build it and expect to see orders come rolling in,\r\nit is not like that. So be prepared to market the business and work\r\nhard to gain traction in your market.</span></font></font></font></p>\r\n<p><span style=\"font-variant-numeric: normal; font-variant-east-asian: normal;\"><font color=\"#000000\"><font face=\"Ubuntu\"><font style=\"font-size: 12pt\"><span style=\"background: transparent\">A\r\ngood tip for e-commerce sites is to learn from the masters. Online\r\ngiants like <a href=\"http://asos.com/\" target=\"_blank\">ASOS</a>\r\ninvest millions into their online strategy, why not piggyback a few\r\nideas from them? So take a look at their website, both on your smartphone and desktop PC to see how they are presenting their products\r\nand organizing their site.</span></font></font></font></span></p>\r\n<p style=\"font-variant-numeric: normal; font-variant-east-asian: normal;\">\r\n<font color=\"#000000\"><font face=\"Ubuntu\"><font style=\"font-size: 12pt\"><span style=\"background: transparent\">§&nbsp;\r\nPersonal Websites: These sites are ideal for individuals to help\r\nshare information and photos with friends. The domain registrar\r\noffers free space, and thus you use that advantage to create a\r\npersonalized site. The first part of your URL has the ISP name\r\n(Internet Service Provider), and the last part has your name as a\r\nperson. These sites have limited server capabilities and are not\r\nsearch engine optimized and hence not ideal for marketing business.</span></font></font></font></p>\r\n<p style=\"font-variant-numeric: normal; font-variant-east-asian: normal;\">\r\n<font color=\"#000000\"><font face=\"Ubuntu\"><font style=\"font-size: 12pt\"><span style=\"background: transparent\">§&nbsp;\r\nNews/Blog Websites: These sites give the latest news in\r\nentertainment, weather, and sports. They offer breaking news, news\r\nupdate concerning the country/ the world and overall global news.</span></font></font></font></p>\r\n<p style=\"font-variant-numeric: normal; font-variant-east-asian: normal;\">\r\n<font color=\"#000000\"><font face=\"Ubuntu\"><font style=\"font-size: 12pt\"><span style=\"background: transparent\">§&nbsp;\r\nConsultation Websites: Just as the name suggests, consultation sites\r\nspecifically design for offering consultative information about\r\nparticular topics. The client gets information on how to solve some\r\nissues and general inquiries about everything in life.</span></font></font></font></p>\r\n<p><span style=\"font-variant-numeric: normal; font-variant-east-asian: normal;\"><font color=\"#000000\"><font face=\"Ubuntu\"><font style=\"font-size: 12pt\"><span style=\"background: transparent\">§&nbsp;\r\nCommunity Building Websites: These popular sites have cropped up in\r\nthe last ten years. They help to connect people online whereby people\r\ncan share ideas, photos, and events. People interact socially hence\r\nthe name social media. The sites include <a href=\"https://www.facebook.com/\" target=\"_blank\">facebook.com</a>,\r\n<a href=\"http://linkedin.com/\" target=\"_blank\">linkedin.com</a>, and\r\n<a href=\"http://myspace.com/\" target=\"_blank\">myspace.com</a>. Photo\r\nsharing sites like <a href=\"http://picasa.com/\" target=\"_blank\">picasa.com</a>\r\nalso fall under this category of websites</span></font></font></font></span></p>\r\n<p><span style=\"font-variant-numeric: normal; font-variant-east-asian: normal;\"><font color=\"#000000\"><font face=\"Ubuntu\"><font style=\"font-size: 12pt\"><span style=\"background: transparent\">§&nbsp;\r\nMLM Matrix and Donation: Multilevel Marketing, or MLM, is a system\r\nfor selling goods or services through a network of distributors.\r\nMultilevel marketing is also referred to as Network Marketing or\r\nDirect Sales. The typical Multilevel Marketing program works through\r\nrecruitment. You are invited to become a distributor (or <a href=\"https://www.thebalancesmb.com/the-advantages-of-being-a-contractor-2948558\" target=\"_blank\">contractor</a>\r\nor consultant or associate), sometimes through another distributor of\r\nthe company\'s products and sometimes through a generally advertised\r\nmeeting.</span></font></font></font></span></p>\r\n<p style=\"font-variant-numeric: normal; font-variant-east-asian: normal;\">\r\n<font color=\"#000000\"><font face=\"Ubuntu\"><font style=\"font-size: 12pt\"><span style=\"background: transparent\">If\r\nyou choose to become a distributor with the direct selling company,\r\nyou\'ll earn money both through the sales of the MLM\'s products and\r\nthrough recruiting other distributors, by receiving a portion of the income these distributors generate And when those distributors\r\nrecruit distributors of their own, you\'ll earn money on the income\r\nthey generate too.</span></font></font></font></p>\r\n<p style=\"font-variant-numeric: normal; font-variant-east-asian: normal;\">\r\n<font color=\"#000000\"><font face=\"Ubuntu\"><font style=\"font-size: 12pt\"><span style=\"background: transparent\">The\r\ndistributors that you sign up with your Multilevel Marketing plan and\r\nthe ones they sign up, in turn, are called you are downline. The\r\ndistributor that originally recruited you and whoever is above him or\r\nher in the recruitment chain is called your upline. Often the\r\ndistributor who recruits you will give you some help getting started,\r\nincluding training.</span></font></font></font></p>\r\n<p style=\"font-variant-numeric: normal; font-variant-east-asian: normal;\">\r\n<font color=\"#000000\">&nbsp;</font></p>\r\n<p style=\"font-variant-numeric: normal; font-variant-east-asian: normal;\">\r\n<font color=\"#000000\"><font face=\"Ubuntu\"><font style=\"font-size: 12pt\"><span style=\"background: transparent\">-&nbsp;\r\n&nbsp; &nbsp; &nbsp; &nbsp; Applications: How many times have you\r\nheard it? There is an app for that. The helpful suggestion offered by\r\na friend who has just heard you complain about some mundane task\r\nyou\'d rather not have to spend your precious free time on in order to\r\nget it off of your to-do list.</span></font></font></font></p>\r\n<p style=\"font-variant-numeric: normal; font-variant-east-asian: normal;\">\r\n<font color=\"#000000\"><span style=\"background: transparent\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n<font face=\"Ubuntu\"><font style=\"font-size: 12pt\">An app is\r\nthe common slang term for a software application or software program\r\nthat can be run on a computer device to accomplish a task easier and\r\nmore efficiently than we could do it ourselves as mere mortals. If\r\nyou have a smartphone or computer tablet, you probably have used some\r\ngame apps, news apps or even map apps to help you find the local\r\ncoffee shop. Application development is the name of the profession\r\nthat employs people who design, develop and deploy this computer applications.</font></font></span></font></p>\r\n<p style=\"font-variant-numeric: normal; font-variant-east-asian: normal;\">\r\n<font color=\"#000000\"><font face=\"Ubuntu\"><font style=\"font-size: 12pt\"><span style=\"background: transparent\">Application\r\ndevelopers have a computer programming background. As you might\r\nimagine, the reason it is called application development instead of\r\njust computer programming is because there are many more steps\r\ninvolved before and after the actual writing of the computer program.\r\nAll of those steps are very typical and are collectively called a\r\nsystems development lifecycle. Muhahe helps you to get those\r\nApplication for your using different programming languages like C,\r\nC#, C++, Java, Visual Basic, ReactJs, Android Apps, Python, Ruby, ……….</span></font></font></font></p>\r\n<p>\r\n<br>\r\n<br>\r\n\r\n</p>', 0),
(5, 'Advertisement solutions', '<style type=\"text/css\">\r\n		@page { margin: 0.79in }\r\n		p { margin-bottom: 0.1in; line-height: 115% }\r\n	</style>\r\n\r\n\r\n<p><font color=\"#000000\"><font style=\"font-size: 12pt\"><b>With\r\nthe help of internet , by using our own website , social medias,\r\ntheir devices , emails and search engines muhahe share marketing\r\nmessage for your products and services so that they get customers.</b></font></font></p>\r\n<p><font color=\"#000000\"><font style=\"font-size: 12pt\"><b>Muhahe\r\nshare your products/services in the following ways:</b></font></font></p>\r\n<p><font color=\"#000000\"><font style=\"font-size: 12pt\"><b><font face=\"Arial\">-</font>&nbsp;\r\n&nbsp; &nbsp;&nbsp;Via Bulk messages</b></font></font></p>\r\n<p><font color=\"#000000\"><font style=\"font-size: 12pt\"><b>Bulk\r\nmessages are sent to all people via the cell phone numbers to\r\nencourage them to buy your products and buy telling them importance\r\nof working with us.</b></font></font></p>\r\n<p><font color=\"#000000\"><font style=\"font-size: 12pt\"><b><font face=\"Arial\">-</font>&nbsp;\r\n&nbsp; &nbsp;&nbsp;Mail Ads</b></font></font></p>\r\n<p><font color=\"#000000\"><font style=\"font-size: 12pt\"><b>We\r\nshare your products to different by mailing them and share them\r\nimages for the products and encouraging them to buy them.</b></font></font></p>\r\n<p><font color=\"#000000\"><font style=\"font-size: 12pt\"><b><font face=\"Arial\">-</font>&nbsp;&nbsp;Display\r\nAds</b></font></font></p>\r\n<p><font color=\"#000000\"><font style=\"font-size: 12pt\"><b>Probably\r\nthe oldest form of online ads, display ads, appear as everything from\r\nbanners of all shapes and sizes to text ads relevant to the content\r\nof a page. You might find an AutoZone display ad on a popular car\r\nblog or a banner ad promoting the newest products at Sephora on a\r\npopular beauty or cosmetics blog.</b></font></font></p>\r\n<p><font color=\"#000000\"><font style=\"font-size: 12pt\"><b><font face=\"Arial\">-</font>&nbsp;&nbsp;Email\r\nAds</b></font></font></p>\r\n<p><font color=\"#000000\"><font style=\"font-size: 12pt\"><b>Email\r\nads are such a popular form of online marketing that many consumers\r\ndon\'t even think about them being advertisements. Open your inbox and\r\nyou are likely to see advertisements promoting new services from your\r\ncable provider, special offers on children\'s clothes from Macy\'s, or\r\nthe latest cell phone gadget from Samsung or Apple. Email ads\r\nsometimes come in the form of coupons or newsletters.</b></font></font></p>\r\n<p><font color=\"#000000\"><font style=\"font-size: 12pt\"><b>-&nbsp;&nbsp;\r\n&nbsp; &nbsp; &nbsp;&nbsp;Search engine marketing, or SEM,</b></font></font></p>\r\n<p><font color=\"#000000\"><font style=\"font-size: 12pt\"><b><span style=\"background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">It\r\nis designed to increase a website\'s visibility in&nbsp;<font face=\"Ubuntu\">search\r\nengine results pages (SERPs). Search engines provide sponsored\r\nresults and organic (non-sponsored) results based on a web searcher\'s\r\nquery. Search engines often employ visual cues to differentiate\r\nsponsored results from organic results. Search engine marketing\r\nincludes all of an advertiser\'s actions to make a website\'s listing\r\nmore prominent for topical keywords. The primary reason behind the\r\nrising popularity of Search Engine Marketing has been Google. A few\r\ncompanies had its own PPC and Analytics tools. However, Google\r\npopularized this concept. Google Ad words was convenient for the\r\nadvertisers to use in addition, create campaigns. In addition, they\r\nrealized that the tool did a fair job, by charging only for someone\'s\r\nclick on the ad, which reported as the cost-per-click for which a\r\npenny was charged. This resulted in the advertisers monitoring the\r\ncampaign by the number of clicks and were satisfied that the ads\r\ncould be</font></span></b></font></font></p>\r\n<p><br>\r\n<br>\r\n\r\n</p>', 0),
(6, 'Buy and Sell products and services online', '<p style=\"text-align: justify; \"><font face=\"times new roman\" style=\"background-color: rgb(255, 255, 255);\"><span style=\"color: rgb(127, 127, 127); font-size: 21.3333px; font-weight: 700; white-space: pre-wrap;\">Muhahe is a global market that gets products from different producers, sellers, and wholesalers and sells them at an affordable price to a different price via our online e-commerce website </span><a href=\"http://www.muhahe.com/\" target=\"_blank\" data-saferedirecturl=\"https://www.google.com/url?q=http://www.muhahe.com&amp;source=gmail&amp;ust=1569944389242000&amp;usg=AFQjCNGkUnNFwm7xDra3dGLFX2I4WP9OoA\" data-saferedirectreason=\"2\" style=\"color: rgb(17, 85, 204); font-size: 21.3333px; font-weight: 700; white-space: pre-wrap;\">www.muhahe.com</a><span style=\"color: rgb(127, 127, 127); font-size: 21.3333px; font-weight: 700; white-space: pre-wrap;\">. Different products are brought in different categories where user gets access to them to add them to cart and buy them using different online payment method like mobile money, visa card, bitcoins, Skrill, Perfect money,… with muhahe no problem of payment. This will reduce much of the time people spend in the market looking for products they want or the time spent at the bank withdrawing money, this also will reduce theft and raise money security. No stress of how the products will reach your place, muhahe deliver you all the products at less/no cost.</span></font></p>', 0),
(7, 'Online Trading Training', '<style type=\"text/css\">\r\n		@page { margin: 0.79in }\r\n		p { margin-bottom: 0.1in; line-height: 115% }\r\n		a:link { so-language: zxx }\r\n	</style>\r\n\r\n\r\n<p style=\"font-variant-numeric: normal; font-variant-east-asian: normal;\">\r\n<font color=\"#000000\"><font face=\"Ubuntu\"><font style=\"font-size: 12pt\"><span style=\"background: transparent\">Have\r\nyou ever heard of online marketing? Have you heard of affiliate\r\nprogram? This is what we do we help people know how they can use low\r\nincome and earn a lot using online trading. We also teach people how\r\nthey can be affiliates and earn money through sharing company’s\r\nproduct.</span></font></font></font></p>\r\n<p><font color=\"#000000\"><font face=\"Ubuntu\"><font style=\"font-size: 12pt\"><span style=\"background: transparent\"><br>\r\n</span></font></font></font><br>\r\n<br>\r\n\r\n</p>', 0),
(8, 'Supplying firefighting system tools', '<style type=\"text/css\">\r\n		@page { margin: 0.79in }\r\n		p { margin-bottom: 0.1in; line-height: 115% }\r\n		a:link { so-language: zxx }\r\n	</style>\r\n\r\n\r\n<p><font color=\"#000000\"><font face=\"Ubuntu\"><font style=\"font-size: 12pt\"><span style=\"background: transparent\"><span style=\"font-variant-numeric: normal; font-variant-east-asian: normal;\">Nowadays\r\nwe all rushing in development where the use of electric power in\r\ndifferent ways like home power, car power, Refrigerators, Cooking,\r\ncooling, different devices like Personal computer, printers,\r\nscanners, clothes dryers, air conditions, ……….. Due to overuse\r\nof them and other factors, this may lead to fire problems Muhahe with\r\nthe help of their technologist and engineers they design you a system\r\nthat will reduce power problems. For the early installed systems, we\r\nprovide you a better way that will be used to fight power problems for\r\nincur case.</span></span></font></font></font></p>', 0);
